(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0025.js"] = [{"id":"poem-a49a298822a2db014fcededc","title":"大车","author":"佚名","dynasty":"先秦","verses":["大车槛槛，毳衣如菼。岂不尔思？畏子不敢。","大车啍啍，毳衣如𫞩，岂不尔思？畏子不奔。","谷则异室，死则同穴。谓予不信，有如皎日。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-72","tags":[]},{"id":"poem-a4a1a17b978bbf0c73cfe608","title":"好事近·今古满胸中","author":"仲并","dynasty":"宋","verses":["今古满胸中，韬略一时人杰。","高卧溪山好处，迟十年斋钺。","朱轓休傍武陵溪，梅花记曾别。","早晚殿前归侍，总周庐千列。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-185","tags":[]},{"id":"poem-a4a7839546af59593649862b","title":"邓隠峰赞","author":"释了惠","dynasty":"宋","verses":["金锡一震，虚空退听。","百万雄兵，难破此阵。","一时游戏神通，未免旁观者哂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ddc926a2-12a1-4d72-a0c0-e6507917af70","tags":[]},{"id":"poem-a4aba10fa396c31ffc08667f","title":"咏史诗 兰台宫","author":"胡曾","dynasty":"唐","verses":["迟迟春日满长空，亡国离宫蔓草中。","宋玉不忧人事变，从游那赋大王风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3b71f76d-6472-4c17-9ff1-b93d028224d8","tags":[]},{"id":"poem-a4ad3d1dfa7390780476b403","title":"复安静堂旧额","author":"王十朋","dynasty":"宋","verses":["端明之孙字子强，银钩铁画传遗芳。","昔年作郡古平海，大笔亲书安静堂。","自从宣和至乾道，字与轮奂争光芒。","一朝忽遭俗眼白，毁灭名姓深埋藏。","我来搜访久乃获，老兵据为寝处床。","涤除五载尘土面，字向堂上增激昂。","祖为第一孙是似，书有家法称莆阳。","体具万安颇雄壮，榜与忠献同翱翔。","因知文字乃至宝，一时之厄庸何伤。","石鼓文有鬼神护，淮西碑并日月光。","岂容泯灭暴秦火，谁肯脍炙段文昌。","书生作郡太迂阔，理财听讼俱非长。","吾君若问何以治，堂复韩蔡祠秦姜。","今才五日京兆耳，眷此陈迹犹未忘。","但愿兹堂日安静，名与国寿俱无疆。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-09ee13c9-7310-444f-8a13-bedc78c0b44e","tags":[]},{"id":"poem-a4b41ed2e3c7d7ac089a3c18","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["孩儿疮疾幸然干。","(合)自今番，常打扮。","(后)沉香亭畔倚阑杆。","(合)夜合花，红牡丹。","姚黄间满，这太湖仙，真个最堪观。","也罗。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2713","tags":[]},{"id":"poem-a4bdef952877c049da7a2a86","title":"日暮天无云","author":"熊孺登","dynasty":"唐","verses":["杳杳复苍然，无云日暮天。","象分青气外，景尽赤霄前。","渐吐星河色，遥生水木烟。","从容难附丽，顾步欲澄鲜。","但见收三素，何能测上玄。","应非暂呈瑞，不许出山川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f5e2ca2f-9094-4b19-a87a-23b411269a9f","tags":[]},{"id":"poem-a4bfa3d2d917c876f47e9ece","title":"题子敬范新妇唐摹帖三首  其一","author":"米芾","dynasty":"宋","verses":["贞观款书丈二纸，不许儿奇专父美。","何为寥寥宝是似，遭乱真归火兼水。","千年谁人能继趾，不自名家殊未智。","嗟尔方来眼须洗，玉躞金题半归米。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e778cb02-79d5-496d-b3a4-dce265d7709a","tags":[]},{"id":"poem-a4c15376e95245eec2621d21","title":"河出荣光","author":"张良器","dynasty":"唐","verses":["引派昆山峻，朝宗海路长。","千龄逢圣主，五色瑞荣光。","隐暎浮中国，晶明助太阳。","坤维连浩漫，天汉接微茫。","丹阙清氛里，函关紫气旁。","位尊常守伯，道泰每呈祥。","习坎灵逾久，居卑德有常。","龙门如可涉，忠信是舟梁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-510310a8-01b0-43a5-9622-4bc31edd5573","tags":[]},{"id":"poem-a4c33faa822623607e227129","title":"雄雉","author":"佚名","dynasty":"先秦","verses":["雄雉于飞，泄泄其羽。我之怀矣，自诒伊阻。","雄雉于飞，下上其音。展矣君子，实劳我心。","瞻彼日月，悠悠我思。道之云远，曷云能来？","百尔君子，不知德行。不忮不求，何用不臧。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-32","tags":[]},{"id":"poem-a4c498ef176696adf37089a5","title":"谢韩监芍药","author":"张栻","dynasty":"宋","verses":["一年春事雨声里，十里扬州梦想边。","眼底名花烦折赠，君家风物自嫣然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ed23aa97-6122-49a5-bf75-c410bc805141","tags":[]},{"id":"poem-a4c6b36915fd7810b4f3e571","title":"残丝曲","author":"卢郢","dynasty":"唐","verses":["春风骀荡吹人衣，残丝罥花曳空飞。","闲愁十丈断不得，雄蜂雌蝶相因依。","高楼夹路凌云起，琐窗鸾柱弹《流水》。","莺声啼老杨柳烟，香梦蒙蒙隔千里。","（见清朱绪曾编《金陵诗徴》卷五。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-34f83ff9-7162-481f-878b-966850561c70","tags":[]},{"id":"poem-a4c8d3340452c3bdb36ef514","title":"乌夜啼·雨馀风露凄然","author":"赵鼎","dynasty":"宋","verses":["雨馀风露凄然。","月流天。","还是年时今夜、照关山。","收别泪。","持杯起。","问婵娟。","问我扁舟流荡、几时还。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-966","tags":[]},{"id":"poem-a4cb2d4e391eeb36cb7489a0","title":"尚书都堂瓦松","author":"李晔","dynasty":"唐","verses":["华省秘僊踪，高堂露瓦松。","叶因春后长，花为雨来浓。","影混鸳鸯色，光含翡翠容。","天然斯所寄，地势太无从。","接栋临双阙，连甍近九重。","宁知深涧底，霜雪岁兼封。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e68b6697-98a2-488a-b620-77a99420cc3b","tags":[]},{"id":"poem-a4d39bc62969786e6c7cf874","title":"雨意  其一","author":"王同祖","dynasty":"宋","verses":["春愁如织雨如麻，倦倚吟窗拾落花。","坐不忍眠心似醉，悠悠身世在天涯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-62adb4fd-99c0-40a8-bd3b-d4c0e3fa5bac","tags":[]},{"id":"poem-a4daf032647bb480e04089e5","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十九","author":"易静","dynasty":"唐","verses":["勾陈将，忌克主行年。","若克行年多败死，行年无（京本作「多」）克见勋全，审细去参诠。","（勾陈克玄武，主胜。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a2d9b3d3-37af-4bc5-90a6-941f18f97686","tags":[]},{"id":"poem-a4e2846c7d2e8f8a4b9c1660","title":"杕杜","author":"佚名","dynasty":"先秦","verses":["有杕之杜，其叶湑湑。独行踽踽。岂无他人？不如我同父。嗟行之人，胡不比焉？人无兄弟，胡不佽焉？","有杕之杜，其叶箐箐。独行睘睘。岂无他人？不如我同姓。嗟行之人，胡不比焉？人无兄弟，胡不佽焉？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-118","tags":[]},{"id":"poem-a4e3b94dddb854363633163a","title":"狮子行道峰","author":"陈岩","dynasty":"宋","verses":["佛力所至物皆化，看取南山金碧堆。","林浮莽伏不衔毒，狮子昔曾行道来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6ee299fd-f861-40cd-894e-81513823f6a8","tags":[]},{"id":"poem-a4e4a20db3f36bcbf35698bc","title":"吴江舟中作","author":"米芾","dynasty":"宋","verses":["昨风起西北，万艘皆乘便。","今风转而东，我舟十五纤。","力乏更雇夫，百金尚嫌贱。","船工怒鬭语，夫坐视而怨。","添槔亦复车，黄胶生口咽。","河泥若祐夫，粘底更不转。","添金工不怒，意满怨亦散。","一曳如风车，叫啖如临战。","傍观鶑窦湖，渺渺无涯岸。","一滴不可汲，况彼西江远。","万事须乘时，汝来一何晚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-31a8afc7-40a7-42de-9a31-16322a139649","tags":[]},{"id":"poem-a4f66ea864c192aad88a6f8f","title":"留别郑三韦九兼洛下诸公","author":"高适","dynasty":"唐","verses":["忆昨相逢论久要，顾君哂我轻常调。","羁旅虽同白社游，诗书已作青云料。","蹇质蹉跎竟不成，年过四十尚躬耕。","长歌达者桮中物，大笑前人身后名。","幸逢明盛多招隐，高山大泽征求尽。","此时亦得辞渔樵，青袍裹身荷圣朝。","犂牛钓竿不复见，县人邑吏来相邀。","远路鸣蝉秋兴发，华堂美酒离忧销。","不知何日更携手，应念兹晨去折腰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b541e528-83cc-4c89-9990-94fda479abdb","tags":[]},{"id":"poem-a4f82b06a8ec4e747265aeda","title":"减字木兰花·多情被恼","author":"向","dynasty":"宋","verses":["多情被恼。","枉了东君无限巧。","真个愁人。","一片轻飞减却春。","阑干凭暖。","目断彩云肠也断。","两岸青山。","隐隐孤舟浪接天。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-202","tags":[]},{"id":"poem-a5025bdabe0d8550cdd14596","title":"生查子·春山烟欲收","author":"牛希济","dynasty":"五代","verses":["春山烟欲收，天淡稀星小。","残月脸边明，别泪临清晓。","语已多，情未了，回首犹重道：记得绿罗裙，处处怜芳草。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-41","tags":[]},{"id":"poem-a502fb53edcd6c4f38943adc","title":"仁寿堂","author":"释居简","dynasty":"宋","verses":["阔开荡荡城中天，朝菌灵椿总大年。","凿井耕田皆帝力，不知谁党复谁偏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3c1c5b44-7ae7-4fdc-bc14-4363bb61f09a","tags":[]},{"id":"poem-a5091fe89b8f5b2be6fe2bf9","title":"次韵和复古春日五绝句  其五","author":"司马光","dynasty":"宋","verses":["燕拂人衣絮扑头，红英满地绿阴稠。","残春举目多愁思，休上迢迢百尺楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-697f109e-62c4-4b2c-b69f-2281a29dd5d9","tags":[]},{"id":"poem-a50b2776346740ec07abc16f","title":"清明日得家书四首  其三","author":"李纲","dynasty":"宋","verses":["欲归归未得，留滞绣江滨。","感慨伤春望，侨居多北人。","苍生未苏息，黄屋尚蒙尘。","王室艰危极，澘然泣老臣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c6337157-a141-417f-b0ac-bfc785405ce2","tags":[]},{"id":"poem-a510d8529fa84f90a3525f0f","title":"江城子·华灯高宴水精宫","author":"沈与求","dynasty":"宋","verses":["华灯高宴水精宫。","浪花中。","意无穷。","十载江湖，重绾汉符铜。","应有青藜存往事，人缥缈，佩丁东。","卧听萧寺响疏钟。","渡溪风。","转空蒙。","月上孤窗，邻唱有渔翁。","追念使君清坐久，歌一发，恨千重。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-818","tags":[]},{"id":"poem-a513a3b82f25620126c5b290","title":"奉和崔中丞使君论李侍御萼登烂柯山宿石桥寺効小谢体","author":"皎然","dynasty":"唐","verses":["常爱谢公郡，幽期愿相从。","果回青骢臆，共蹑玄仙踪。","灵境若髣髴，烂柯思再逢。","飞梁丹霞接，古局苍苔封。","往想冥昧理，谁亲冰雪容。","蕙楼耸空界，莲宇开中峰。","昔化冲虚鹤，今藏护法龙。","云窥香树沓，月见色天重。","永夜寄岑寂，清言涤心胸。","盛游千年后，书在岩中松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-10837c16-9587-4251-84fe-69d822946433","tags":[]},{"id":"poem-a51a6242ef7c5c203cb9e503","title":"送康祭酒赴轮台","author":"曹唐","dynasty":"唐","verses":["灞水桥边酒一杯，送君千里赴轮台。","霜黏海眼旗声冻，风射犀文甲缝开。","断碛簇烟山似米，野营轩地鼓如雷。","分明会得将军意，不斩楼兰不拟回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f6ff95f0-d92f-4414-a409-46cb0d088510","tags":[]},{"id":"poem-a51b5ccc20c292a7da5b9812","title":"贡院图","author":"王十朋","dynasty":"宋","verses":["陈君少年登甲科，红莲首泛清源波。","清源贡宇高嵳峩，同僚宣力陈君多。","鞭朴不施成不日，首夏上梁秋半毕。","一点灵台轮奂飞，十幅生绡画图出。","苍苍嘉木森千株，新堤步步穿芙蕖。","移下蟾宫古丹桂，飞来海上真蓬壶。","他年君来作地主，记得亲曾视斤斧。","雁过山中寄我书，要知多少新龙虎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-61c7ec0d-55d3-4d48-9d82-2ac590b62ba4","tags":[]},{"id":"poem-a5270456c2d33560aa267795","title":"临江仙·海棠香老春江晚","author":"和凝","dynasty":"五代","verses":["海棠香老春江晚，小楼雾縠涳蒙。","翠鬟初出绣帘中，麝烟鸾鬟苹风。","碾玉钗摇㶉𫛶战，雪肌云鬓将融。","含情遥指碧波东，越王台殿蓼花红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-15","tags":[]},{"id":"poem-a527a3531f7814bf6864e27c","title":"滕王阁","author":"张乔","dynasty":"唐","verses":["昔人登览处，遗阁大江隅。","叠浪有时有，闲云无日无。","早凉先燕去，返照后帆孤。","未得营归计，菱歌满旧湖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3e8f3ce8-4766-4896-9420-ded8b2856a36","tags":["滕王阁"]},{"id":"poem-a5322f6347b98c9dbd6b704f","title":"虞美人·好风微揭帘旌起","author":"孙光宪","dynasty":"五代","verses":["好风微揭帘旌起，金翼鸾相倚。","翠檐愁听乳禽声，此时春态暗关情，独难平。","画堂流水空相翳，一穗香摇曳。","教人无处寄相思，落花芳草过前期，没人知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-8","tags":[]},{"id":"poem-a53ddc1441a756ddc07e81b9","title":"辞见闻颂","author":"智闲","dynasty":"唐","verses":["好住迳分离，幽宗人迹稀。","从来未登陟，无许遣狐疑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4cf66848-655a-46a8-a896-4230dc0bbe4b","tags":[]},{"id":"poem-a5631d0d6bd5a31a07bf795f","title":"寒食日题杜鹃花","author":"曹松","dynasty":"唐","verses":["一朵又一朵，并开寒食时。","谁家不禁火，总在此花枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8c993f97-ee32-4756-8db7-df0514aa7c5d","tags":[]},{"id":"poem-a566bdfa625f3c6c25dc1d95","title":"清平乐·弹琴峡题壁","author":"纳兰性德","dynasty":"清","verses":["泠泠彻夜，谁是知音者。","如梦前朝何处也，一曲边愁难写。","极天关塞云中，人随落雁西风。","唤取红襟翠袖，莫教泪洒英雄。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-121","tags":[]},{"id":"poem-a56a09ec7a840d8d3b41e7b3","title":"题靖节祠  其一","author":"孙勴","dynasty":"宋","verses":["先生拂衣归柴桑，视时富贵犹粃糠。","义心耻食易代粟，督邮于我何低昂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a16f724e-6197-4447-bffd-4197b89da74c","tags":[]},{"id":"poem-a56d17e9b5380475b12fc392","title":"句  其五","author":"释赞宁","dynasty":"宋","verses":["与闲为活计。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-417e809e-4074-4507-8da8-b3af000125c2","tags":[]},{"id":"poem-a56d472e460dc193ce727557","title":"减字木兰花·新月","author":"纳兰性德","dynasty":"清","verses":["晚妆欲罢，更把纤眉临镜画。","准待分明，和雨和烟两不胜。","莫教星替，守取团圆终必遂。","此夜红楼，天上人间一样愁。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-82","tags":[]},{"id":"poem-a576736a86f3bc1498cbad24","title":"至墨离海奉怀敦煌知己","author":"佚名","dynasty":"唐","verses":["朝行傍海涯，暮宿幕为家。","千山空皓雪，万里尽黄沙。","戎俗途将近，知音道已赊。","回瞻云岭外，挥涕独咨嗟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-bee2b4b7-bcfd-43b2-aecd-9c3b6c9a694a","tags":[]},{"id":"poem-a5785d870b4b279e3fb8cd39","title":"赠皇甫侍御赴都八首 七","author":"元希声","dynasty":"唐","verses":["会合非我，关山坐违。","离鸿晓引，别叶秋飞。","𬴂骖徐动，尊饯相依。","远情超忽，岐路光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ed24afb2-20d1-4065-b30d-adf31e1adacc","tags":[]},{"id":"poem-a5786515fc8954c3fcf66007","title":"闲中有富贵","author":"司马光","dynasty":"宋","verses":["闲中有富贵，迥与俗尘殊。","水浄齐纨展，花繁蜀锦纡。","竹风寒扣玉，荷雨急跳珠。","可笑公孙衍，酣歌夸丈夫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e65fc924-1163-4e47-8ef0-43183e5a6d0e","tags":[]},{"id":"poem-a579783387bcf328edafa1e2","title":"夏日金陵制幕即事  其五","author":"王同祖","dynasty":"宋","verses":["入夏边烽渐报安，不妨拄笏共观山。","西风易把江涛涌，整暇规摹肯放闲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bcecb025-51fe-4258-8cbb-b6e56026eff6","tags":[]},{"id":"poem-a5861ea9fe66fbe17a468ed5","title":"二郎神·深深院","author":"王十朋","dynasty":"宋","verses":["深深院。","夜雨过，帘栊高卷。","正满槛、海棠开欲半。","仍朵朵、红深红浅。","遥认三千宫女面。","匀点点、胭脂未遍。","更微带、春醪宿醉，袅娜香肌娇艳。","日暖。","芳心暗吐，含羞轻颤。","笑繁杏夭桃争烂漫。","爱容易、出墙临岸。","子美当年游蜀苑。","又岂是、无心眷恋。","都只为、天然体态，难把诗工裁翦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-556","tags":[]},{"id":"poem-a586ca688bf5b84588ed90cd","title":"夜行船·弄水馀英溪畔","author":"毛滂","dynasty":"宋","verses":["弄水馀英溪畔。","绮罗香、日迟风慢。","桃花春浸一篙深，画桥东、柳低烟远。","涨绿流红空满眼。","倚兰桡、旧愁无限。","莫把鸳鸯惊飞去，要歌时、少低檀板。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-838","tags":[]},{"id":"poem-a58bfff125d3ea685f4e86e9","title":"山居雨霁即事","author":"张碧","dynasty":"唐","verses":["结茅苍岭下，自与喧卑隔。","况值雷雨晴，郊原转岑寂。","出门看反照，绕屋残溜滴。","古路绝人行，荒陂响蝼蝈。","篱崩瓜豆蔓，圃坏牛羊迹。","断续古祠鸦，高低远村笛。","喜闻东臯润，欲往未通屐。","杖策试危桥，攀萝瞰苔壁。","邻翁夜相访，缓酌聊跂石。","新月出污尊，浮云在巾舃。","常隳腐儒操，谬习经邦画。","有待时未知，非关慕沮溺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fd50445d-5cb4-40c4-b2b4-c24f1b205aa2","tags":[]},{"id":"poem-a5909cba509dc8f65b4704a5","title":"送王牧往吉州谒王使君叔","author":"李嘉祐","dynasty":"唐","verses":["细草绿汀洲，王孙耐薄游。","年华初冠带，文体旧弓裘。","野渡花争发，春塘水乱流。","使君怜小阮，应念倚门愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c03ba182-6545-4ebb-8758-ecb1989b981b","tags":["送别","春天","惜别"]},{"id":"poem-a59206bcf739bdf56ad9316d","title":"一斛珠·风流太守","author":"王质","dynasty":"宋","verses":["风流太守。","未春先试回春手。","天寒修竹斜阳后。","翠袖中间，忽有人红袖。","天香国色浓如酒。","且教青女休僝僽。","梅花元是群花首。","细细商量，只怕梅花瘦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-327","tags":[]},{"id":"poem-a59c84cefc6f71f76fe4d282","title":"江上闻猨","author":"雍裕之","dynasty":"唐","verses":["枫岸月斜明，猨啼旅梦惊。","愁多肠易断，不待第三声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-72dcbb00-71cf-41e7-ac0e-3be3588a0e8e","tags":[]},{"id":"poem-a5a08256def95626e67f2b72","title":"江行无题一百首 二十五","author":"钱珝","dynasty":"唐","verses":["佳节虽逢菊，浮生正似萍。","故山何处望，荒岸小长亭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8a267130-ba2d-4914-8b82-5df29e273085","tags":[]},{"id":"poem-a5a0a482b2fa1d70a8397dc3","title":"客中览镜","author":"于邺","dynasty":"唐","verses":["何当开此镜，即见发如丝。","白日急于水，少年能几时。","每逢芳草处，长返故园迟。","所以多为客，蹉跎欲怨谁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0fd9a554-119c-456a-8d4e-b52a5b460163","tags":[]},{"id":"poem-a5ad0c30e08ef94e3c5eec38","title":"江中风","author":"杨凌","dynasty":"唐","verses":["白浪暗江中，南泠路不通。","高樯帆自满，出浦莫呼风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-bbab6661-1d07-4485-86d3-d0b6e6a9159d","tags":[]},{"id":"poem-a5b6b811dbab97597614a240","title":"怀周朴张为","author":"贯休","dynasty":"唐","verses":["二子无消息，多应各自耕。","巴江思杜甫，漳水忆刘桢。","白发应全白，生涯作么生。","寄书多不达，空念重行行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5c957047-1970-4e2a-95ff-18018f2fa0b5","tags":[]},{"id":"poem-a5b821182c04b869908fc1b8","title":"奉和池州杜员外南亭惜春","author":"张祜","dynasty":"唐","verses":["草雾辉辉柳色新，前山差掩黛眉频。","碧溪潮涨碁侵夜，红树花深醉度春。","几恨今年提已过，翻悲昨日事成尘。","可知屈转江南郡，还就封州咏白苹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-03348032-d1f9-40cf-b35a-29e297a52709","tags":[]},{"id":"poem-a5c75858955e17b57f025569","title":"老人峰","author":"陈岩","dynasty":"宋","verses":["佝偻形容古貌浑，旁连众岭似儿孙。","荒山太古万万古，眼见游人来几番。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-58a3ae5f-4142-437d-ac55-331e56c5a37b","tags":[]},{"id":"poem-a5c9bf783662a72a7f427f9b","title":"赠道者","author":"马戴","dynasty":"唐","verses":["深居白云穴，静注赤松经。","往往龙潭上，焚香礼斗星。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5d5c1773-a552-4415-8c5a-c303a7f13260","tags":[]},{"id":"poem-a5cda5f2f5b0b2eecc08068e","title":"南海子·分弓列戟四门开","author":"纳兰性德","dynasty":"清","verses":["分弓列戟四门开，游豫长陪万乘来。","七十二桥天汉上，彩虹飞下晾鹰台。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-223","tags":[]},{"id":"poem-a5d44a9b91bd100d3fd9f99c","title":"减字木兰花·大江北去","author":"陈瓘","dynasty":"宋","verses":["大江北去。","未到沧溟终不住。","淮水东流。","日夜朝宗亦未休。","香炉烟袅。","浓淡卷舒终不老。","寸碧千锺。","人醉华胥月色中。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-547","tags":[]},{"id":"poem-a5d6b4007dd464544fd77acb","title":"塞北二首 一","author":"沈佺期","dynasty":"唐","verses":["虏障天骄起，秦城地脉分。","柏坛飞五将，梅吹动三军。","锋刃奔涛色，旌旗焰火文。","朔风吹汗漫，飘砾洒轒辒。","海气如秋雨，边烽似夏云。","二庭无岁月，百战有功勋。","形影随鱼贯，音书在雁群。","归来拜天子，凯乐助南薰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-385583d6-9a4d-4e07-baf6-256cb67f49bf","tags":[]},{"id":"poem-a5d7a14a475a8ee02accbbc5","title":"地藏塔","author":"陈岩","dynasty":"宋","verses":["八十四级山头石，五百余年地藏坟。","风撼塔铃天半语，众人都向梦中闻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-37f62573-f188-4e53-be32-1c53537a75b8","tags":[]},{"id":"poem-a5db23c5f15031d77bdef77f","title":"岘山送裴秀才赴举","author":"皎然","dynasty":"唐","verses":["汉家招秀士，岘上送君行。","万里见秋色，两河伤远情。","王师出西镐，虏寇避东平。","天府登名后，回看楚水清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-78063f93-fa73-41bd-91fb-55554f27c210","tags":[]},{"id":"poem-a5dcd30fe65db18237044b9c","title":"汉阴庭树","author":"赵嘏","dynasty":"唐","verses":["掘沟引水浇蔬圃，插竹为篱护药苗。","杨柳如丝风易乱，梅花似雪日难消。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b09746fa-a6d8-42a1-a0e6-b803d7d90ed4","tags":[]},{"id":"poem-a5ddbc6dc02f7fb970d0d306","title":"送淡公 二","author":"孟郊","dynasty":"唐","verses":["坐爱青草上，意含沧海滨。","渺渺独见水，悠悠不问人。","镜浪洗手绿，剡花入心春。","虽然防外触，无奈饶衣新。","行当译文字，慰此吟殷勤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-36d5b37a-fcc1-4f31-9234-0ff7fba0036b","tags":[]},{"id":"poem-a5e58e07c4b5dd0269d408af","title":"独游二首 二","author":"皎然","dynasty":"唐","verses":["临水兴不尽，虚舟可同嬉。","还云与归鸟，若共山僧期。","世事吾不预，此心谁得知。","西峰有禅老，应见独游时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-16ea8a69-f21b-42cc-ac32-f59752a88248","tags":[]},{"id":"poem-a5f4494f2cddf866eadabd76","title":"长信草","author":"崔国辅","dynasty":"唐","verses":["长信宫中草，年年愁处生。","故侵珠履迹，不使玉阶行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dfedded9-b444-499e-8547-d80a5d51feb7","tags":[]},{"id":"poem-a6022b4e3f2f6a04f9f9769e","title":"山中道者","author":"苏拯","dynasty":"唐","verses":["筇杖六尺许，坐石流泉所。","举头看古松，似对仙鹤语。","是时天气清，四迥无尘侣。","顾我笑相迎，知有丹砂异。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dccaae80-d48f-4071-bab5-52a00fc01ce7","tags":[]},{"id":"poem-a609e03d44ed1f87c1d6a6bc","title":"失调名·扇开仙掌","author":"蔡","dynasty":"宋","verses":["扇开仙掌。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-700","tags":[]},{"id":"poem-a61d71186f0a639053fd7485","title":"悼赵清献公抃","author":"释法泉","dynasty":"宋","verses":["仕也邦为瑞，归欤世作程。","人间金粟去，天上玉楼成。","慧剑无纤缺，冰壶彻底清。","春风瀔水路，孤月照云明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8e4e51a5-17e3-48ea-94c9-2d2da03ce29d","tags":[]},{"id":"poem-a636377fbcfdd4cefe46653d","title":"春日会饮怀丘思同林成之作四首 次林韵","author":"苏颂","dynasty":"宋","verses":["二月中和气序均，酒酣偏觉长精神。","之人欢会何稀阔，惆怅尊前更惜春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-bfb3efcd-23e0-4d87-8ca3-54cac5717818","tags":[]},{"id":"poem-a63735dec14ad68b6d8e6747","title":"应诏赋得除夜","author":"史青","dynasty":"唐","verses":["今岁今宵尽，明年明日催。","寒随一夜去，春逐五更来。","气色空中改，容颜暗里回。","风光人不觉，已著后园梅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7c339c18-2e14-4988-ba44-43ea5456e44d","tags":["春节"]},{"id":"poem-a63c2a0bb8326686eeb7d8ed","title":"又和董氏东园桧屏石床","author":"司马光","dynasty":"宋","verses":["密叶萧森翠幕纡，暂来犹恨不长居。","脱冠解带坐终日，花落石床春自如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f209e49d-b073-4237-9f94-a636027bd417","tags":[]},{"id":"poem-a6491adeb07b5af6c1f6a779","title":"山居卧疾广利大师见访","author":"崔道融","dynasty":"唐","verses":["桐谷孙枝已上弦，野人犹卧白云边。","九天飞锡应相诮，三到行朝二十年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4c6d58fb-45bb-4da0-9a27-c47b583dffc9","tags":[]},{"id":"poem-a649670d75f62cf58b95f417","title":"奉和华清宫观行香应制","author":"崔国辅","dynasty":"唐","verses":["天子蘂珠宫，楼台碧落通。","豫游皆汗漫，斋处即崆峒。","云物三光里，君臣一气中。","道言何所说，宝历自无穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-46e89ba4-b83f-4183-af4a-1267b3a5afa4","tags":[]},{"id":"poem-a64e83795ac8ce1eb8d8b44b","title":"京口送朱昼之淮南","author":"李涉","dynasty":"唐","verses":["两行客泪愁中落，万树山花雨后残。","君到扬州见桃叶，为传风水渡江难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e4fd3ddc-578e-4335-b6e9-3acdd5e0e235","tags":[]},{"id":"poem-a64fe2d944c19be41793dbc7","title":"送施州单员外","author":"徐铉","dynasty":"宋","verses":["精金百炼始知难，何似仙枝两度攀。","名逐凤书归故里，身从鸟道入巴山。","诏宣远俗皇恩厚，惠洽齐民利刃闲。","珍重加餐顺风土，归来高步七人班。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f5de7cd0-ee1c-4ee4-b7bb-bb03b7393052","tags":[]},{"id":"poem-a655ce78c961af2ef48d786d","title":"和直禁省","author":"杨凝","dynasty":"唐","verses":["宵直丹宫近，风传碧树凉。","漏稀银箭滴，月度网轩光。","凤诏裁多暇，兰灯梦更长。","此时颜范贵，十步旧连行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-567571c0-a3a0-4e62-aa91-565636b1fd6f","tags":[]},{"id":"poem-a65aeef846067f0051838ae3","title":"紫骝马","author":"沈佺期","dynasty":"唐","verses":["青玉紫骝鞍，骄多影屡盘。","荷君能剪拂，躞蹀喷桑干。","踠足追奔易，长鸣遇赏难。","𪭢金一万里，霜露不辞寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-17e061a9-a122-419c-aa21-215d37c4e3e1","tags":[]},{"id":"poem-a65c90786e14f96cf0a8564f","title":"颂","author":"义昭","dynasty":"唐","verses":["虎头生角人难措，石火电光须密布。","假饶烈士也应难，懵底那能解差（《五灯会元》作「回」）互。","（见《景德传灯录》卷二十三、《五灯会元》卷八。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-de9ee6b3-f1ca-4173-ab91-44b2cbcd1fee","tags":[]},{"id":"poem-a6628c203e218e08ceccbe46","title":"书梅福殿壁二首 一","author":"张乔","dynasty":"唐","verses":["梅真从羽化，万古是须臾。","此地名空在，西山云亦孤。","井痕平野水，坛级上春芜。","纵有双飞鹤，年多松已枯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-68ee25ca-ce4a-45ac-83bc-70f0ca0679cb","tags":[]},{"id":"poem-a665d36e90789b2c4a9b0571","title":"见色便见心颂","author":"本先","dynasty":"唐","verses":["若是见色便见心，人来问著方难答。","更求道理说多般，孤负平生三事衲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ea95db3f-9de6-4fef-9d65-c3d9494b95f9","tags":[]},{"id":"poem-a66d0243eff2e514f0797376","title":"鬓云松令·枕函香","author":"纳兰性德","dynasty":"清","verses":["枕函香，花径漏。","依约相逢，絮语黄昏后。","时节薄寒人病酒，刬地梨花，彻夜东风瘦。","掩银屏，垂翠袖。","何处吹箫，脉脉情微逗。","肠断月明红豆蔻，月似当时，人似当时否。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-149","tags":[]},{"id":"poem-a66e91ea43a41c5d9f121d8c","title":"奉和圣制荅张说南出雀鼠谷","author":"崔翘","dynasty":"唐","verses":["硖路绕河汾，晴光拂曙氛。","笳吟中岭树，仗入半峰云。","顿觉山原尽，平看邑里分。","早行芳草迥，晚憩好风熏。","嘉颂推英宰，春游扈圣君。","共欣承睿渥，日月照天文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d0e731e2-f5c3-412d-8aef-36ca8f5bf159","tags":[]},{"id":"poem-a676d76b5d789500519a6bee","title":"贡院垂成双莲呈瑞因成鄙语勉士子","author":"王十朋","dynasty":"宋","verses":["大厦垂垂就，嘉莲得得开。","双双戴千物，两两应三台。","欢意重重合，香风比比来。","人人宜自勉，举举有廷魁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-9d070915-ae07-43b0-bad3-b973b8d3adc8","tags":[]},{"id":"poem-a6805be1a32c535a745fca1b","title":"浣溪沙·晚逐香车入凤城","author":"张泌","dynasty":"五代","verses":["晚逐香车入凤城，东风斜揭绣帘轻，慢回娇眼笑盈盈。","消息未通何计是，便须佯醉且随行，依稀闻道太狂生。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-35","tags":[]},{"id":"poem-a68495133f76edca9390f7d8","title":"常州孟谏议座上闻韩员外职方贬国子博士有感五首 二","author":"卢仝","dynasty":"唐","verses":["干禄无便佞，宜知黜此身。","员郎犹小小，国学大频频。","孤宦心肝直，天王苦死嗔。","朝廷无谏议，谁是雪韩人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5f6cb8bf-c3fd-410b-abe2-01174beb3dbb","tags":[]},{"id":"poem-a686e1a552039e3e173aab19","title":"甘棠","author":"佚名","dynasty":"先秦","verses":["蔽芾甘棠，勿翦勿伐，召伯所茇。","蔽芾甘棠，勿翦勿败，召伯所憩。","蔽芾甘棠，勿翦勿拜，召伯所说。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-15","tags":[]},{"id":"poem-a68fc350b2fef78c5ab9e6d0","title":"留春令·画屏天畔","author":"晏几道","dynasty":"宋","verses":["画屏天畔，梦回依约，十洲云水。","手拈红笺寄人书，写无限、伤春事。","别浦高楼曾漫倚。","对江南千里。","楼下分流水声中，有当日、凭高泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-34","tags":["宋词三百首"]},{"id":"poem-a692ac7b5c9ea16095c2ecc9","title":"行路难 三","author":"贯休","dynasty":"唐","verses":["君不见道傍废井生古木，本是骄奢贵人屋。","几度美人照影来，素绠银缾濯纤玉。","云飞雨散今如此，绣闼雕甍作荒谷。","沸渭笙歌君莫夸，不应常是西家哭。","休谁遗编行者几，至竟终须合天理。","败他成此亦何功，苏张终作多言鬼。","行路难，行路难，不在羊肠里。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d7df0412-a577-49e5-aa8b-adb1a3d8d635","tags":[]},{"id":"poem-a6a4c3fb887d57be129f07c8","title":"洛阳女儿行","author":"王维","dynasty":"唐","verses":["洛阳女儿对门居，才可容颜十五余。","良人玉勒乘骢马，侍女金盘鲙鲤鱼。","画阁朱楼尽相望，红桃绿柳垂簷向。","罗帏送上七香车，宝扇迎归九华帐。","狂夫富贵在青春，意气骄奢剧季伦。","自怜碧玉亲教舞，不惜珊瑚持与人。","春窗曙灭九微火，九微片片飞花璅。","戏罢曾无理曲时，妆成秪是薰香坐。","城中相识尽繁华，日夜经过赵李家。","谁怜越女颜如玉，贫贱江头自浣纱。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4925c861-b0f8-4b2f-923e-9cba2df1323e","tags":["唐诗三百首","生活","女子","乐府","新乐府辞"]},{"id":"poem-a6a4f3f74967a3005f1ae8fa","title":"饯许州宋司马赴任","author":"徐坚","dynasty":"唐","verses":["旧许星车转，神京祖帐开。","断烟伤别望，零雨送离杯。","辞燕依空遶，宾鸿入听哀。","分襟与秋气，日夕共悲哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-cb7d5cc0-b4b6-49fa-95d0-a9d67836aa5b","tags":[]},{"id":"poem-a6a625eb133d4f17d18cc85d","title":"长林令衞象饧丝结歌","author":"司空曙","dynasty":"唐","verses":["主人雕盘盘素丝，寒女眷眷墨子悲。","乃言假使饧为之，八珍重沓失颜色。","手援玉筯不敢持，始状芙蓉新出水。","仰坼重衣倾万蕊，又如合欢交乱枝。","红茸向暮花参差，吴蚕络茧抽尚绝。","细缕纤毫看欲灭，雪发羞垂倭堕鬟。","绣囊畏并茱萸结，我爱此丝巧。","妙绝世间无，为君作歌陈座隅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e3855367-0506-4851-a0e0-289ce9bf8f7e","tags":[]},{"id":"poem-a6a8f514fab4a7b1b905637a","title":"送湖南提刑安学士  其二","author":"华镇","dynasty":"宋","verses":["节遇中秋挟日余，哲人来契梦熊时。","神澄晓露珠凝彩，气爽秋风桂有枝。","歌袴始喧清赣曲，使星还照碧湘西。","太平天子方求旧，但指松椿祝寿祺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b11f1d30-88ba-4bfc-a585-35ccc7d8db8f","tags":[]},{"id":"poem-a6b8989c28c38c18bea7b3dc","title":"鹧鸪天·子夜封章扣紫清","author":"张孝祥","dynasty":"宋","verses":["子夜封章扣紫清。","五霞光里佩环声。","驿传风火龙鸾舞，步入烟宵孔翠迎。","瑶简重，羽衣轻。","金童双引到通明。","三湘五管同民乐，万岁千秋与帝龄。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-232","tags":[]},{"id":"poem-a6c15e05777b9b63ae5571bd","title":"主人故亭","author":"王建","dynasty":"唐","verses":["主人昔专城，城南起高亭。","贵与宾客游，工者夜不宁。","酒食宴圃人，栽接望早成。","经年使家僮，远道求异英。","郡中暂闲暇，遶树引诸生。","开泉浴山禽，为爱山中声。","世间事难保，一日各徂征。","死生不相及，花落实方荣。","我来至此中，守吏非本名。","重君昔为主，相与下马行。","旧岛日日摧，池水不复清。","岂无后人赏，所贵手自营。","浇酒向所思，风起如有灵。","此去不重来，重来伤我形。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-cc77a4a0-3e5c-456f-8bf2-739e4ec6e477","tags":[]},{"id":"poem-a6da06c331f21dfbec66a535","title":"寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 肥河维舟阻冻袛待勅命 二","author":"李绅","dynasty":"唐","verses":["淮阳效理空多病，疎受辞荣岂恋班。","陈力不任趋北阙，有家无处寄东山。","疲骖岂念前程税，倦鸟安能待暮还。","珍重八公山下叟，不劳重泪更追攀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a8daf794-d044-4e48-9e93-d3f2199fb848","tags":[]},{"id":"poem-a6dcb3002bddecb26664dc85","title":"偶诗五首 三","author":"司空图","dynasty":"唐","verses":["贤豪出处尽沉吟，白日高悬只照心。","一掬信陵坟上土，便如碣石累千金。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a7fe5386-9eb3-4e4a-8b6c-ee05be62ace0","tags":[]},{"id":"poem-a6e4e227adb25f3552c36172","title":"春暮途中","author":"李咸用","dynasty":"唐","verses":["细雨如尘散暖空，数峰春色在云中。","须知触目皆成恨，纵道多文争那穷。","飞燕有情依旧阁，垂杨无力受东风。","谁能会得乾坤意，九土枯荣自不同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b4210c74-a311-49ed-aa4c-6a97d6553958","tags":[]},{"id":"poem-a6e559232e777de42818d729","title":"传言玉女·眉黛轻分","author":"袁","dynasty":"宋","verses":["眉黛轻分，惯学玉真梳掠。","艳容可画，那精神怎貌。","鲛绡映玉，钿带双穿缨络。","歌音清丽，舞腰柔弱。","宴罢瑶池，御风跨皓鹤。","凤凰台上，有萧郎共约。","一面笑开，向月斜褰珠箔。","东园无限，好花羞落。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-836","tags":[]},{"id":"poem-a6ebd9d3429e90a26f0d9494","title":"蝶恋花·高下亭台山水境","author":"黄裳","dynasty":"宋","verses":["高下亭台山水境。","两畔清辉，中有垂杨径。","鹭点前汀供雪景。","花乘流水传春信。","不醉无归先说定。","醉待言归，又被风吹醒。","月下壶天游未尽。","广寒宫是波中影。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-609","tags":[]},{"id":"poem-a6ed978b945fecea47c23e04","title":"句","author":"久则","dynasty":"唐","verses":["湖上青山今欲买，白云无主问何人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1aa79f3d-ea1e-43ce-b9f8-b7fbe376379b","tags":[]},{"id":"poem-a6f11c096580fa573a962c92","title":"和严揆省中宿斋遇令狐员外当直之作","author":"李逢吉","dynasty":"唐","verses":["致斋分直宿南宫，越石卢谌此夜同。","位极班行犹念旧，名题章奏亦从公。","曾驱爪士三边静，新赠髯参六义穷。","竟夕文昌知有月，可怜如在庾楼中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3b54bcc9-2aa7-43ec-8d3c-2e29138e5a3a","tags":[]},{"id":"poem-a6f63371debb2243d3d47be8","title":"割飞二刀子歌","author":"卢纶","dynasty":"唐","verses":["我家有翦刀，人云鬼国铁。","裁罗裁绮无钝时，用来三年一股折。","南中匠人淳用钢，再令盘屈随手伤。","改锻割飞二刀子，色迎霁雪锋含霜。","两条神物秋冰薄，刃淬初蟾鞘金错。","越戟吴钩不足夸，斩犀切玉应怀怍。","日试曾磨汉水边，掌中恄栗声冷然。","神惊魄悸却收得，刃头已吐微微烟。","刀乎刀乎何烨烨，魑魅须藏怪须慑。","若非良工变尔形，只向裁缝委箱箧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-19710654-694f-4c8b-a46f-7eaf13ff8570","tags":[]},{"id":"poem-a6f7302c7fba8a37df5c6e6e","title":"送薛良史往越州谒从叔","author":"崔峒","dynasty":"唐","verses":["辞家年已久，与子分偏深。","易得相思泪，难为欲别心。","孤云随浦口，几日到山阴。","遥想兰亭下，清风满竹林。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-377fd9dd-3ab4-4bb4-8eaa-6a5334b38d14","tags":[]},{"id":"poem-a6fcde7105df46877e1bc89e","title":"游山","author":"鲍溶","dynasty":"唐","verses":["白道行深云，云高路弥细。","时时天上客，遗路人间世。","烟花最深处，井臼得空刺。","天寒鹤巢林，石长泉脉闭。","神化万灵集，心期一朝契。","不见金板书，谁知阮家裔。","终期太古人，问取松柏岁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e10f90db-3c4b-427a-9748-733582b40c60","tags":[]},{"id":"poem-a6ff774ad4de7adfaf58c4ad","title":"粉蝶儿","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外上］一片襟期，清似五湖秋水，喜声名上达丹墀。","感皇恩，蒙圣宠，迁除福地。","秉忠心肃清奸弊。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8203","tags":[]},{"id":"poem-a7013861440cbe59af63a752","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 一","author":"易静","dynasty":"唐","verses":["太乙式，逆顺论阴阳。","五日六时成一局，八门九曜遂（辛本、川本作「逐」）时当，凶吉利门方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f6ed8fc8-5dea-4bbd-b058-25b2c8b6feef","tags":[]},{"id":"poem-a709e2e63035aec4451d664e","title":"寄四明闾丘道士二首 二","author":"贯休","dynasty":"唐","verses":["三千功未了，大道本无程。","好共禅师好，墙将药犬行。","石门红藓剥，柘坞白云生。","莫认无名是，无名已是名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a5007e8b-4da7-4ec3-8c63-07bb32b86b76","tags":[]},{"id":"poem-a70cdd4c79032a2b6243c22c","title":"羽林行","author":"王建","dynasty":"唐","verses":["长安恶少出名字，楼下劫商楼上醉。","天明下直明光宫，散入五陵松柏中。","百回杀人身合死，赦书尚有收城功。","九衢一日消息定，乡吏籍中重改姓。","出来依旧属羽林，立在殿前射飞禽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-83ebd852-25b4-44fa-a74e-76aba64b063f","tags":["隋・唐・五代","写人","讽刺"]},{"id":"poem-a710bf1841155b4f72a096ee","title":"山花子","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["玳筵开处游人拥，争看五百名英雄。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4984","tags":[]},{"id":"poem-a714b56755056f580bda4319","title":"八阵图","author":"杜甫","dynasty":"唐","verses":["功盖三分国，名高八阵图。","江流石不转，遗恨失吞吴。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-927908c0-999f-4d3f-8192-d67d28f93576","tags":["唐诗三百首","隋・唐・五代","怀古","哲理","写人","五言绝句"]},{"id":"poem-a717a9bfa65b6d5facedec1b","title":"班婕妤怨歌","author":"纳兰性德","dynasty":"清","verses":["团团望舒月，皓皓冰蚕绢。","欲却炎天暑，比月裁成扇。","望舒圆易缺，金风换炎节。","风凉秋气寒，匣扇复谁看。","扇弃何足道，感妾伤怀抱。","对月泪如丝，君恩异旧时。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-256","tags":[]},{"id":"poem-a71c68c726f8d7a8f9af54c7","title":"晚次鄂州","author":"卢纶","dynasty":"唐","verses":["云开远见汉阳城，犹是孤帆一日程。","估客昼眠知浪静，舟人夜语觉潮生。","三湘衰鬓逢秋色，万里归心对月明。","旧业已随征战尽，更堪江上鼓鼙声。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fae577a5-da28-4672-83ff-94c97ae2a4a4","tags":["唐诗三百首","战争","写景","抒情","七言律诗","思乡"]},{"id":"poem-a723455f352525646cfa8b1f","title":"郊庙歌辞 武后大享拜洛乐章 昭和","author":"不详","dynasty":"唐","verses":["九玄眷命，三圣基隆。","奉承先旨，明台毕功。","宗祀展敬，冀表深衷。","永昌帝业，式播淳风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6aa54435-8335-4fff-959a-c6b92f8d9080","tags":[]},{"id":"poem-a7380b94ecd5e12225099b8b","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["不留伊是它不要汝，你须是早寻着归路。","你不早省，教伊孤苦。","(净)敢直恁底负它贫女。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2635","tags":[]},{"id":"poem-a742f275ebc9a59b5a62807e","title":"浣溪沙·枕障熏炉隔绣帷","author":"张泌","dynasty":"五代","verses":["枕障熏炉隔绣帷，二年终日两相思，杏花明月始应知。","天上人间何处去，旧欢新梦觉来时，黄昏微雨画帘垂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-32","tags":[]},{"id":"poem-a7499a0bae6081d8369106c1","title":"凤栖梧・蝶恋花·惆怅留春留不住","author":"杜安世","dynasty":"宋","verses":["惆怅留春留不住。","欲到清和，背我堂堂去。","飞絮落花和细雨。","凄凉庭院流莺度。","更被闲愁相赚误。","梦断高唐，回首桃源路。","一饷沈吟无意绪。","分明往事今何处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-910","tags":[]},{"id":"poem-a75247ffc6e0ef2231079685","title":"破阵子·燕子欲归时节","author":"晏殊","dynasty":"宋","verses":["燕子欲归时节，高楼昨夜西风。","求得人间成小会，试把金尊傍菊丛。","歌长粉面红。","斜日更穿帘幕，微凉渐入梧桐。","多少襟怀言不尽，写向蛮笺曲调中。","此情千万重。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-429","tags":[]},{"id":"poem-a752b083a7ea73d62aecc916","title":"踏莎行·波湛横眸","author":"张先","dynasty":"宋","verses":["波湛横眸，霞分腻脸。","盈盈笑动笼香靥。","有情未结凤楼欢，无憀爱把歌眉敛。","密意欲传，娇羞未敢。","斜偎象板还偷盰。","轻轻试问借人么，佯佯不觑云鬟点。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-271","tags":[]},{"id":"poem-a752e3625d5017694c13045d","title":"胡无人行","author":"聂夷中","dynasty":"唐","verses":["男儿徇大义，立节不沽名。","腰间悬陆离，大歌胡无行。","不读战国书，不览黄石经。","醉卧咸阳楼，梦入受降城。","更愿生羽翼，飞身入青冥。","请携天子劒，斫下旄头星。","自然胡无人，虽有无战争。","悠哉典属国，驱羊老一生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4a3e9cc5-e2a2-412d-a884-4c17d072c5a2","tags":[]},{"id":"poem-a75f95e1b2589c3ddf83b462","title":"青蝇","author":"佚名","dynasty":"先秦","verses":["营营青蝇，止于樊。岂弟君子，无信谗言。","营营青蝇，止于棘。谗人罔极，交乱四国。","营营青蝇，止于榛。谗人罔极，构我二人。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-218","tags":[]},{"id":"poem-a765a40c3bfa26ce14682151","title":"左丞相说右丞相璟太子少傅乾曜同日上官命宴东堂赐诗","author":"明皇帝","dynasty":"唐","verses":["赤帝收三杰，黄轩举二臣。","由来丞相重，分掌国之钧。","我有握中璧，双飞席上珍。","子房推道要，仲子讶风神。","复辍台衡老，将为调护人。","鹓鸾同拜日，车骑拥行尘。","乐聚南宫宴，觞连北斗醇。","俾予成百揆，垂拱问彝伦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d1ba29c5-333c-4b5d-978f-d5bfdf29a89b","tags":[]},{"id":"poem-a7725bd0c6c6718b580870bf","title":"法雄寺东楼","author":"张籍","dynasty":"唐","verses":["汾阳旧宅今为寺，犹有当时歌舞楼。","四十年来车马绝，古槐深巷暮蝉愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-42a7ef88-90f5-4f79-abbf-bf05bd87bc9e","tags":[]},{"id":"poem-a7729a7635a54d23346af299","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["告神祗，神圣听咨启，可怜三日无粮米。","泪偷垂，只得撮土为香，拜告天和地。","神圣，别人赌钱，十赌九赢，偏我智远呵……。","蒲牌买快时，蒲牌买快时。","十番九遍输，望神圣与我空中庇。","呀！你看旌幡队队，鼓乐喧天，想是赛会的来了。","不免躲在供桌底下，取些福礼充饥，有何不可？正是一日不识羞，三日不忍饿。","(躲介。","外、老旦上)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8808","tags":[]},{"id":"poem-a7778eedba5a43ce105dc86b","title":"李夫人二首 二","author":"徐夤","dynasty":"唐","verses":["招得香魂爵少翁，九华灯烛晓还空。","汉王不及吴王乐，且与西施死处同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-411f1c67-19e7-4de2-8843-c4bb63f2ef2e","tags":[]},{"id":"poem-a77b43e11af5140418986a8d","title":"秋日登岳阳楼晴望","author":"张碧","dynasty":"唐","verses":["三秋倚练飞金盏，洞庭波定平如刬。","天高云卷绿罗低，一点君山碍人眼。","漫漫万顷铺琉璃，烟波阔远无鸟飞。","西南东北竞无际，直疑侵断青天涯。","屈原回日牵愁吟，龙宫感激致应沈。","贾生憔悴说不得，茫茫烟霭堆湖心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-efad3f8b-87d3-406e-a916-fc8fb2bdf381","tags":["洞庭湖","岳阳楼"]},{"id":"poem-a77dd3d77c9c694aacd8360b","title":"送赵栖岩分司池阳总干","author":"释居简","dynasty":"宋","verses":["九华空众山，尤物在尘寰。","迥出云雨上，朝来眉睫间。","有人皆毓胜，无豹不藏斑。","官舍轩楹豁，凭阑莫掩关。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-456d4329-4d96-42e9-84e3-6f47f4fd9235","tags":[]},{"id":"poem-a784db5c8fd9fc0d70c71d9b","title":"游长宁公主流杯池二十五首 二十一","author":"上官昭容","dynasty":"唐","verses":["傍池聊试笔，倚石旋题诗。","豫弹山水调，终拟从钟期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0279adf4-af13-41e9-b12a-a094f2860a06","tags":[]},{"id":"poem-a788fc540ddc3af7ba5b60e0","title":"寄李儋元锡","author":"韦应物","dynasty":"唐","verses":["去年花里逢君别，今日花开已一年。","世事茫茫难自料，春愁黯黯独成眠。","身多疾病思田里，邑有流亡愧俸钱。","闻道欲来相问讯，西楼望月几廻圆。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8435b46d-bbf1-49e5-af66-6f2d5681f1bf","tags":["唐诗三百首","思念","友人","忧国忧民","七言律诗"]},{"id":"poem-a7a46fed5407a18e043830e6","title":"偈七首  其二","author":"释法泉","dynasty":"宋","verses":["团团离海峤，渐渐出云衢。","此夜一轮满，清光何处无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-68040408-4e36-48ba-aea3-cd46672468dd","tags":["写诗","中秋节","赏月"]},{"id":"poem-a7a9224b090dc0ce3b38a2a6","title":"追凉历下古城西北隅此地有清泉乔木","author":"卢象","dynasty":"唐","verses":["谢朓出华省，王祥贻佩刀。","前贤真可慕，衰病意空劳。","贞悔不自卜，游随共尔曹。","未能齐得丧，时复诵离骚。","闲荫七贤地，醉餐三士桃。","苍苔虞舜井，乔木古城壕。","渔父偏相狎，尧年不可逃。","蝉鸣秋雨霁，云白晓山高。","咫尺传双鲤，吹嘘借一毛。","故人皆得路，谁肯念同袍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a351ea47-24d1-4371-99e1-9b67d41e6b92","tags":[]},{"id":"poem-a7b2c4c90ce163b8596057bb","title":"海眼光赞","author":"释了惠","dynasty":"宋","verses":["海眼为香饵，悲心作钓钩。","鱼龙知几许，贪者自擡头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9fa14616-a893-4c86-af0e-b33f40bfb5ba","tags":[]},{"id":"poem-a7c4d2469a86decf289e0ce3","title":"送曾裘父","author":"张栻","dynasty":"宋","verses":["交旧间何阔，能来浃日留。","还寻佳橘颂，惜别仲宣楼。","探古书盈屋，忧时雪满头。","绝思黄阁老，招隠意绸缪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-cb1580cf-aeb1-4494-97f8-45c2f9ccdb53","tags":[]},{"id":"poem-a7cabc2aa18c106abb218742","title":"蜡梅","author":"曾协","dynasty":"宋","verses":["小树列仙质，翛然道家装。","雪帔挂浅绛，铢衣曳微黄。","清风一披拂，芝兰让幽香。","老子专鼻观，此花正相当。","就令困霜雪，肯受泥涂伤。","题评得名字，诗人惜辉光。","虽无调鼎实，不作时世粧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-423fb257-8cee-4612-ba4a-e74622426f73","tags":[]},{"id":"poem-a7d534d9c0e8f1483010c581","title":"荆湖望月","author":"张栻","dynasty":"宋","verses":["浩浩湖之源，迤逦衡山下。","有月来中天，明珠千斛泻。","澂澈一尘无，交辉清不夜。","嗟彼泉下人，逝莫挽逸驾。","惟有不死心，清光徧华夏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ef5b31b4-8412-48f0-93ab-8807b2097115","tags":["衡山"]},{"id":"poem-a7e3bbf26dcd0e7f5a250272","title":"眼儿媚·咏红姑娘","author":"纳兰性德","dynasty":"清","verses":["骚屑西风弄晚寒，翠袖倚阑干。","霞绡裹处，樱唇微绽，靺鞨红殷。","故宫事往凭谁问，无恙是朱颜。","玉墀争采，玉钗争插，至正年间。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-93","tags":[]},{"id":"poem-a7ee9d6b6ecc39a32370c42d","title":"鼓吹曲辞 凯歌六首 二","author":"岑参","dynasty":"唐","verses":["官军西出过楼兰，营幕傍临月窟寒。","蒲海晓霜凝劒尾，葱山夜雪扑旌竿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-436ddce1-56b4-4d4b-a0e0-2101cf9cebb3","tags":[]},{"id":"poem-a7ef8689793707439d29b2e3","title":"赠融上人","author":"皎然","dynasty":"唐","verses":["常爱西林寺，池中月出时。","芭蕉一片叶，书取寄吾师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6edd2d8d-fbb2-4709-9ea5-e6091d26b3e5","tags":[]},{"id":"poem-a7f09d752719d85ce8b90ae2","title":"鱼山神女祠歌 迎神","author":"王维","dynasty":"唐","verses":["坎坎击鼓，鱼山之下。","吹洞箫，望极浦，女巫进，纷屡舞。","陈瑶席，湛清酤，风凄凄兮夜雨。","不知神之来兮不来，使我心兮苦复苦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-1a6e884e-e9fb-4564-81f5-9b937d3c74b1","tags":[]},{"id":"poem-a7f7c3d549fa4e08c354d22f","title":"前岁过真阳初识子钦今道出曲江不忍遽分手偶成长句以志两处山川人物之胜亦少慰别来耿耿耳","author":"林光朝","dynasty":"宋","verses":["秋崖一夕卷炎蒸，那更挥斤为斲冰。","碧落旧寻烧药灶，白芒长对读书灯。","相期大庾何多日，似出浮屠向上层。","纵有分张吾未老，定从台阁看飞腾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-affa66f7-b196-4e24-b257-74f2cace17eb","tags":[]},{"id":"poem-a7fa9f20a11ed86d0513396c","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)出语大相欺，九州按抚是我为品级。","都堂爵位掌管一十五万官兵，权显达还乡里。","我妆旧时私探你，休泄漏莫与外人知。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8990","tags":[]},{"id":"poem-a80cad72ebad42b0df59f027","title":"秋胡行 其二","author":"曹操","dynasty":"汉","verses":["愿登泰华山，神人共远游。","愿登泰华山，神人共远游。","经历昆仑山，到蓬莱。","飘遥八极，与神人俱。","思得神药，万岁为期。","歌以言志，愿登泰华山。","天地何长久！人道居之短。","天地何长久！人道居之短。","世言伯阳，殊不知老；赤松王乔，亦云得道。","得之未闻，庶以寿考。","歌以言志，天地何长久！","明明日月光，何所不光昭！","明明日月光，何所不光昭！","二仪合圣化，贵者独人不？","万国率土，莫非王臣。","仁义为名，礼乐为荣。","歌以言志，明明日月关。","四时更逝去，昼夜以成岁。","四时更逝去，昼夜以成岁。","大人先天而天弗违。","不戚年往，忧世不治。","存亡有命，虑之为蚩。","歌以言志，四时更逝去。","戚戚欲何念！欢笑意所之。","戚戚欲何念！欢笑意所之。","壮盛智愚，殊不再来。","爱时进趣，将以惠谁？","泛泛放逸，亦同何为！","歌以言志，戚戚欲何念！"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-17","tags":[]},{"id":"poem-a8176def6dbf5bd674efb3df","title":"淇奥","author":"佚名","dynasty":"先秦","verses":["瞻彼淇奥，绿竹猗猗。有匪君子，如切如磋，如琢如磨，瑟兮僴兮，赫兮咺兮。有匪君子，终不可谖兮。","瞻彼淇奥，绿竹青青。有匪君子，充耳秀莹，会弁如星。瑟兮僴兮。赫兮咺兮，有匪君子，终不可谖兮。","瞻彼淇奥，绿竹如箦。有匪君子，如金如锡，如圭如璧。宽兮绰兮，猗重较兮。善戏谑兮，不为虐兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-54","tags":[]},{"id":"poem-a81d31d3806c94d4a54b2695","title":"自淇涉黄河途中作十三首 十","author":"高适","dynasty":"唐","verses":["茫茫浊河注，怀古临河滨。","禹功本豁达，汉迹方因循。","坎德昔滂沱，冯夷胡不仁。","激潏陵堤防，东郡多悲辛。","天子忽惊悼，从官皆负薪。","畚筑岂无谋，祈祷如有神。","宣房今安在，高岸空嶙峋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cea51298-9d8e-468f-a075-8e843c97e018","tags":["黄河"]},{"id":"poem-a8232824d1b2e30c6c6d979d","title":"九月八日送萧少府归洪州","author":"皎然","dynasty":"唐","verses":["明日重阳今日归，布帆丝雨望霏霏。","行过鹤渚知堪住，家在龙沙意有违。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-36a820f5-686d-4ce1-94d9-58e2edc15f00","tags":[]},{"id":"poem-a83430675cba6afa8293f5db","title":"梦到沙州奉怀殿下","author":"佚名","dynasty":"唐","verses":["一从沦陷自天涯，数度恓（原作「栖」）惶怨别家。","将谓飘零长失路，谁知运合至流沙。","浪漫有幸达人主，惟恨天才遇尚赊。","日夕恩波沾雨露，纵横顾盼益光华。","光华远近谁不羡，常思刷羽抟风便。","忽使三冬告别离，山河万里诚难见。","昨来魂梦傍阳关，省到敦煌奉玉颜。","舞席歌楼似登陟，绮筳花柳记跻攀。","总缘宿昔承言笑，此夜论心岂𫏐闲。","睡里不知回早晚，觉时只觉泪斑斑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7b426457-5aa7-4e8a-91a5-24464c4dead8","tags":[]},{"id":"poem-a83bb420692705a16e39ea47","title":"赠巩畴","author":"郑薰","dynasty":"唐","verses":["密雪松桂寒，书窗导余清。","风憾冰玉碎，阶前琴磬声。","榻静几砚洁，帙散缣缃明。","高论展僧肇，精言资巩生。","立意加玄虚，析理分纵横。","万化悉在我，一物安能惊。","江海何所动，丘山常自平。","迟速不相阂，后先徒起争。","镜照分妍丑，秤称分重轻。","颜容宁入鉴，铢两岂关衡。","蕴微道超忽，剖镫音泠泠。","纸上掣牢键，舌端摇利兵。","圆澈保直性，客尘排妄情。","有住即非住，无行即是行。","疏越舍朱弦，哇淫鄙秦筝。","淡薄贵无味，羊斟慙大羹。","洪远包乾坤，幽窅潜沈冥。","罔烦跬步举，顿达万里程。","庐远尚莫晓，隐留曾误听。","直须持妙说，共诣毗耶城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-33a668cd-706d-4c0d-9228-64c0c7aa533a","tags":[]},{"id":"poem-a8450e5fdecc48d62f2264be","title":"寄冯使君","author":"贯休","dynasty":"唐","verses":["山风与霜气，浩浩满松枝。","永日烧杉子，无人共此时。","为文攀讽谏，得道在毫厘。","唯有桐江守，常怜志不卑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-510ab4a1-3617-4cc0-a1f5-0e7e561f5448","tags":[]},{"id":"poem-a8586e83e22978ac2b5a45f7","title":"还乡偶书  其二","author":"黄拱","dynasty":"唐","verses":["少小离家老大回，乡音难改鬓毛衰。","儿童相见不相识，借问客从何处来。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-569ef0e1-887d-4d98-b869-9634f099c8e9","tags":["二年级上册","唐诗三百首","伤老","七言绝句","思乡","感慨","小学古诗"]},{"id":"poem-a85aea7ace006b85bbbf46d8","title":"下山虎","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["见鞍思马，睹物伤情。","触起关心事，怎不泪零？如今我婿得沐圣朝宠荣，我女一身成画饼。","他取我到吉城，值此寒冬，怎出外境？(合)天寒地冷，未可离乡背井，且待春和款款行。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8296","tags":[]},{"id":"poem-a864c0e20c25d767e8cc4080","title":"秋怀","author":"林之奇","dynasty":"宋","verses":["槭槭庭树叶，朝零非昔稠。","呦呦草虫鸣，暮急晓未休。","尔虫无不平，岂亦有哀忧。","胡为劳呻吟，与士感伤投。","壮士亦何者，哀哦与虫酬。","所抱不列陈，调苦难谣讴。","极目有远见，直怀羞曲求。","蒿藜袭久安，功名忘前收。","日月忽未几，天地今复秋。","少壮负所怀，老大安能谋。","生无及人功，死骨埋泉羞。","胡为不奋飞，徒与寒饿雠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-be9882c1-678d-472d-9f5e-3c3f38a48ed3","tags":[]},{"id":"poem-a865f2641dc9cfb86b592504","title":"尚书新造花笺","author":"徐夤","dynasty":"唐","verses":["浓染红桃二月花，只宜神笔纵龙蛇。","浅澄秋水看云母，碎擘轻苔间粉霞。","写赋好追陈后宠，题诗堪送窦滔家。","使君即入金銮殿，夜直无非草白麻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ba028a2f-decc-4bfb-abe3-15ab300eb410","tags":[]},{"id":"poem-a86a4ccb229ad8f1eb3810fd","title":"雨后净望河西连山怆然成咏","author":"李德裕","dynasty":"唐","verses":["宿雨初收晚吹繁，秋光极目自销魂。","烟山北下归辽海，鸿鴈南飞出蓟门。","只恨无功书史籍，岂悲临老事戎轩。","唯怀药饵蠲衰病，为惜余年报主恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6e8e68b8-2bc4-4ec7-aa42-bb030326e72a","tags":[]},{"id":"poem-a87629a434ab63a7818c30b8","title":"望远行","author":"萧德祥《小孙屠》","dynasty":"元","verses":["离了故乡，跋涉崎岖劳攘。","水宿风餐，旅况怎消遣？(末上)那日方离家乡，回首家乡怎想？且缓步徐徐行上。","(婆)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8647","tags":[]},{"id":"poem-a88bfa2ad406a54386d8c1e0","title":"西江月·天地才经否泰","author":"张伯端","dynasty":"宋","verses":["天地才经否泰，朝昏好识屯蒙。","辐来辏毂水朝宗。","妙在抽添运用。","得一万般皆毕，休分南北西东。","损之又损慎前功。","命宝不宜轻弄。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-976","tags":[]},{"id":"poem-a88ed379f5764a963b63404d","title":"上巳忆江南禊事","author":"李德裕","dynasty":"唐","verses":["黄河西绕郡城流，上巳应无祓禊游。","为忆渌江春水色，更无宵梦向吴州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3d23c60b-3b57-42b4-89b8-09d75abcf2d7","tags":["黄河"]},{"id":"poem-a89c1668b04b90dd8344c6f5","title":"寄清泠山道人","author":"贯休","dynasty":"唐","verses":["常忆清泠子，深云种早禾。","万缘虽不涉，一句子如何。","踪迹诸峰匝，衣裳老虱多。","江头无事也，终必到烟萝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e61110c9-d584-4cea-ab75-1fcd50a9e4ac","tags":[]},{"id":"poem-a89c434c94965f4f78bf0db2","title":"传婆井","author":"吕从庆","dynasty":"唐","verses":["古井无渊源，千秋自涵养。","日暮汲人来，洞然发清响。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9b0b585a-5ea2-4ec8-989d-ed1e52c57735","tags":[]},{"id":"poem-a8a3bb82fe131b8fb41d50e2","title":"宫怨","author":"任翻","dynasty":"唐","verses":["泪乾红落脸，心尽白垂头。","自此方知怨，从来岂信愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f69af4c2-f99b-4593-a732-969d99243fd3","tags":[]},{"id":"poem-a8acba01ecdbf0df0900fcb9","title":"春秋战国门 田文","author":"周昙","dynasty":"唐","verses":["下客常才不足珍，谁为狗盗脱强秦。","秦关若待鸡鸣出，笑杀临淄土偶人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-1959138b-5885-46ef-8843-7833bfb71d78","tags":[]},{"id":"poem-a8af8230d85c436046161abb","title":"和梁签判颍州西湖十三题 撷芳亭","author":"苏颂","dynasty":"宋","verses":["春来何处最花繁，湖水西头百亩园。","无限游人折红蕊，可怜桃李自无言。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-242806ad-dd23-40f2-a816-73e76f1aca01","tags":["西湖"]},{"id":"poem-a8b25e0ab572af419fc48371","title":"歌者十二首 一","author":"司空图","dynasty":"唐","verses":["追逐翻嫌傍管弦，金钗击节自当筵。","风霜一夜燕鸿断，唱作江南袚禊天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a9a565c5-f80e-4d54-8526-85791275c919","tags":[]},{"id":"poem-a8b35d87c1c9cf03ccf2e56a","title":"采桑子·时光只解催人老","author":"晏殊","dynasty":"宋","verses":["时光只解催人老，不信多情。","长恨离亭。","泪滴春衫酒易醒。","梧桐昨夜西风急，淡月胧明。","好梦频惊。","何处高楼雁一声。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-467","tags":[]},{"id":"poem-a8c36d15878c01d99e31d45c","title":"柳含烟·章台柳","author":"毛文锡","dynasty":"五代","verses":["章台柳，近垂旒。","低拂往来冠盖，鞭胧春色满皇州，瑞烟浮。","直与路边江畔别，免被离人攀折。","最怜京兆画蛾眉，叶纤时。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-19","tags":[]},{"id":"poem-a8c58c905b55adc7863870a4","title":"王神童","author":"释居简","dynasty":"宋","verses":["夙慧虽无蔕，抽萌便不凡。","兰薰腾玉砌，侯国荐冰衔。","荷橐行须复，牙签尽疗馋。","一经千佛字，先把客儿搀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-63439d69-ab7a-4c53-bd81-5b17af0cc138","tags":[]},{"id":"poem-a8c880f088a401e7365acd6e","title":"破阵子","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(外上)野外江山幽雅，城中景物繁华；(贴旦、旦、丑上)六街三市堪描画，万紫千红实可夸。","(合)闽城景最佳。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8252","tags":[]},{"id":"poem-a8cfd7a1ddfa1d8bb46d188a","title":"家兄有和再用韵  其一","author":"艾可翁","dynasty":"宋","verses":["隔林看日落，出户对天行。","久乱人情变，长贫心事明。","虹拖城郭势，河泻甲兵声。","谁似秋来水，能于浊世清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-50bbd500-1f46-4ba3-a261-fe6b1618c45c","tags":[]},{"id":"poem-a8d6cc8e3ecbad5f263046bb","title":"临江仙·扪窗摸户入房来","author":"邢俊臣","dynasty":"宋","verses":["扪窗摸户入房来。","笙歌归院落，灯火下楼台。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-841","tags":[]},{"id":"poem-a8d9a7299d156dddb2c3b0bc","title":"九叹·怨思","author":"刘向","dynasty":"汉","verses":["惟郁郁之忧毒兮，志坎𡒄而不违。","身憔悴而考旦兮，日黄昏而长悲。","闵空宇之孤子兮，哀枯杨之冤雏。","孤雌吟于高墉兮，鸣鸠栖于桑榆。","玄蝯失于潜林兮，独偏弃而远放。","征夫劳于周行兮，处妇愤而长望。","申诚信而罔违兮，情素洁于纽帛。","光明齐于日月兮，文采耀燿于玉石。","伤压次而不发兮，思沉抑而不扬。","芳懿懿而终败兮，名靡散而不彰。","背玉门以奔骛兮，蹇离尤而干诟。","若龙逢之沉首兮，王子比干之逢醢。","念社稷之几危兮，反为雠而见怨。","思国家之离沮兮，躬获愆而结难。","若青蝇之伪质兮，晋骊姬之反情。","恐登阶之逢殆兮，故退伏于末庭。","孽臣之号咷兮，本朝芜而不治。","犯颜色而触谏兮，反蒙辜而被疑。","菀蘼芜与菌若兮，渐藁本于洿渎。","淹芳芷于腐井兮，弃鸡骇于筐簏。","执棠谿以刜蓬兮，秉干将以割肉。","筐泽泻以豹鞟兮，破荆和以继筑。","时溷浊犹未清兮，世殽乱犹未察。","欲容与以俟时兮，惧年岁之既晏。","顾屈节以从流兮，心巩巩而不夷。","宁浮沅而驰骋兮，下江湘以邅回。","叹曰：山中槛槛余伤怀兮，征夫皇皇其孰依兮，经营原野杳冥冥兮，乘骐骋骥舒吾情兮，归骸旧邦莫谁语兮，长辞远逝乘湘去兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-49","tags":[]},{"id":"poem-a8dd859c7281d6787a8b262b","title":"送高司直寻封阆州","author":"杜甫","dynasty":"唐","verses":["丹雀衔书来，暮栖何乡树。","骅骝事天子，辛苦在道路。","司直非冗官，荒山甚无趣。","借问泛舟人，胡为入云雾。","与子姻娅间，即亲亦有故。","万里长江边，邂逅一相遇。","长卿消渴再，公干沈緜屡。","清谈慰老夫，开卷得佳句。","时见文章士，欣然澹情素。","伏枕闻别离，畴能忍漂寓。","良会苦短促，溪行水奔注。","熊罴咆空林，游子慎驰骛。","西谒巴中侯，艰险如跬步。","主人不世才，先帝常特顾。","拔为天军佐，崇大王法度。","淮海生清风，南翁尚思慕。","公宫造广厦，木石乃无数。","初闻伐松柏，犹卧天一柱。","我瘦书不成，成字读亦误。","为我问故人，劳心练征戍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-26587ca4-6af1-4180-a430-b29652a14f1d","tags":["长江"]},{"id":"poem-a8e72f99abfdf4f0b1034fe0","title":"陪子华燕醮厅酒半过赵中令园","author":"司马光","dynasty":"宋","verses":["簪裾丞相阁，林沼令君家。","烟曲香寻篆，杯深酒过花。","霏微烬沈水，馥郁渍榠柤。","愧乏相如赋，陪游托后车。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-3a300d56-47be-4ac0-b0bc-a72a6a8c872c","tags":[]},{"id":"poem-a8eb8b7ba879da29dc6dbee0","title":"送李喻之处士洪州谒曹王","author":"皎然","dynasty":"唐","verses":["独思贤王府，遂作豫章行。","雄镇庐霍秀，高秋江汉清。","见闻惊苦节，艰故伤远情。","西邸延嘉士，遗才得正平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ce2d35e0-f4b0-4409-971e-f7c02826fb65","tags":[]},{"id":"poem-a8f02ef2825ab7977a28c014","title":"菩萨蛮·越梅半坼轻寒里","author":"和凝","dynasty":"五代","verses":["越梅半坼轻寒里，冰清淡薄笼蓝水。","暖觉杏梢红，游丝狂惹风。","闲阶莎径碧，远梦犹堪惜。","离恨又迎春，相思难重陈。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-17","tags":[]},{"id":"poem-a8f8647813174636203df09c","title":"避寇入银山","author":"贯休","dynasty":"唐","verses":["草草穿银峡，崎岖路未谙。","傍山为店戍，永日绕溪潭。","烧地生芚蕨，人家煮伪蚕。","翻如归旧隐，步步入烟岚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9ba76ba7-23d1-4762-a9f7-2050c3a228da","tags":[]},{"id":"poem-a8fdf0f988640b232e1e333b","title":"苑中人日遇雪应制","author":"赵彦昭","dynasty":"唐","verses":["始见青云干律吕，俄逢瑞雪应阳春。","今日回看上林树，梅花柳絮一时新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6ea04e5b-c451-4f23-9914-a5dd163bc169","tags":[]},{"id":"poem-a90f6b48d320850af79e9c0c","title":"句","author":"郄殷象","dynasty":"唐","verses":["鸳鸯分品秩，龙衮耀簪裾。","（见《吟窗杂录》卷十三王梦简《进士王氏诗要格律》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-da87bda5-b585-4530-8705-756e153a3ad2","tags":[]},{"id":"poem-a914e6ff28b99a475bad90fe","title":"十二咏 磬塘","author":"李纲","dynasty":"宋","verses":["乔木森森借绿阴，曲塘波影漾疏林。","龟鱼不用愁清浅，藻荇菰蒲隐映深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5160e4bb-d1cb-4247-a6bc-7e3ade248b3e","tags":[]},{"id":"poem-a925545ba529f0f1cf2ad8df","title":"圆明后葬者居祖塔前属寺僧树表以识之","author":"释居简","dynasty":"宋","verses":["小桥南北尽僧居，仿佛天花傍镜湖。","支遁厩中多养骏，丈人屋上试占乌。","轩窗面面云痕湿，楼观层层水影孤。","惆怅门前一抔土，倩谁封殖戒樵苏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-31c127de-4f35-4589-90e0-d8da99bb1440","tags":[]},{"id":"poem-a93134a554cbdffd66d53f43","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十一","author":"易静","dynasty":"唐","verses":["日奇合，九地见开门。","探审贼机扬虚阵，遥虚设假利偷营，鬼遁隐神兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-36a07fe4-4781-4c5a-af95-94472099ad48","tags":[]},{"id":"poem-a93154a3bcb28222a42a2b41","title":"题青龙兴化禅院方丈","author":"李纲","dynasty":"宋","verses":["廓然丈室湛虚明，地僻山空万象清。","滴翠老杉清净色，锵金流水妙圆声。","慇懃禅客邀迎厚，寂寞宰官身世轻。","野鹤孤云无不可，会须还作二龙行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d19b0a85-4a9b-4541-977a-f67d0cfb1c7c","tags":[]},{"id":"poem-a9394cadca6448ca149706ea","title":"贺明朝·忆昔花间初识面","author":"欧阳炯","dynasty":"五代","verses":["忆昔花间初识面，红袖半遮妆脸。","轻转石榴裙带，故将纤纤玉指，愉捻双凤金线。","碧梧桐锁深深院，谁料得，两情何日教缱绻。","羡春来双燕，飞到玉楼，朝暮相见。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-9","tags":[]},{"id":"poem-a939d87d8f0ab451569a4904","title":"菩萨蛮·当时携手今千里","author":"蔡伸","dynasty":"宋","verses":["当时携手今千里。","可堪重到相逢地。","触目尽关心。","流莺尚好音。","无人知我意。","只有涓涓泪。","寂寞到斜阳。","罗衣裛旧香。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-980","tags":[]},{"id":"poem-a93b138f4792bb48941839a9","title":"宿楚国寺有怀","author":"赵嘏","dynasty":"唐","verses":["风动衰荷寂寞香，断烟残月共苍苍。","寒生晚寺波摇壁，红堕疎林叶满床。","起雁似惊南浦棹，阴云欲护北楼霜。","江边松菊荒应尽，八月长安夜正长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-23f92364-8920-49e3-9b7f-d9c70cfcbf95","tags":[]},{"id":"poem-a93f057c694cc716ae821c15","title":"追酬故高蜀州人日见寄","author":"杜甫","dynasty":"唐","verses":["自蒙蜀州人日作，不意清诗久零落。","今晨散帙眼忽开，迸泪幽吟事如昨。","呜呼壮士多慷慨，合沓高名动寥廊。","叹我凄凄求友篇，感时郁郁匡君略。","锦里春光空烂熳，瑶墀侍臣已冥莫。","潇湘水国傍鼋鼍，鄠杜秋天失雕鹗。","东西南北更谁论，白首扁舟病独存。","遥拱北辰缠寇盗，欲倾东海洗乾坤。","边塞西蕃最充斥，衣冠南渡多崩奔。","鼓瑟至今悲帝子，曳裾何处觅王门。","文章曹植波澜阔，服食刘安德业尊。","长笛谁能乱愁思，昭州词翰与招魂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3057f1b2-f2c5-482d-a9c8-b4d1a02125e9","tags":[]},{"id":"poem-a93f96c9499371dd2f906c12","title":"明月棹孤舟·海淀","author":"纳兰性德","dynasty":"清","verses":["一片亭亭空凝伫。","趁西风霓裳偏舞。","白鸟惊飞，菰蒲叶乱，断续浣纱人语。","丹碧驳残秋夜雨。","风吹去采菱越女。","辘轳声断，昏鸦欲起，多少博山情绪。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-254","tags":[]},{"id":"poem-a944ce2b7878d81e23ddd357","title":"故观文建安刘公挽诗四首  其三","author":"张栻","dynasty":"宋","verses":["平日多奇节，中间似富公。","天从庐墓请，人说救荒功。","辛苦培邦本，雍容遏乱锋。","文传遗奏切，更过子囊忠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-df9f2149-af8e-4eb7-accb-3a711d2f8176","tags":[]},{"id":"poem-a95633cd1f4dc849ea235791","title":"种桑","author":"释居简","dynasty":"宋","verses":["无衣可柰何，桑树百余窠。","拙计不及此，瘠田谁种它。","绿荷供楚制，白苎入吴歌。","金谷虽佳丽，知谁所得多。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7c5471e7-e0ec-4310-b4ec-5b3452423185","tags":[]},{"id":"poem-a95dc246b640f29c08233ca0","title":"杨柳枝·苏小门前柳万条","author":"温庭筠","dynasty":"唐","verses":["苏小门前柳万条，毵毵金线拂平桥。","黄莺不语东风起，深闭朱门伴舞腰。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-31","tags":[]},{"id":"poem-a961e2eef45bbf4a62752a15","title":"亨杞下第作诗示之","author":"司马光","dynasty":"宋","verses":["清白君家旧，文章时态新。","何妨偶蹉跌，未必遂沈沦。","莫叹科名晚，惟忧道谊贫。","进修专在已，得失尽由人。","孝友亦为政，箪瓢足养亲。","那将少年泪，容易輙伤春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1d10e298-1131-43a1-87ad-0fc4e6ad45fe","tags":[]},{"id":"poem-a96343e5203a0b5bf53a66e3","title":"罗稚川善画作此赠之","author":"赵文","dynasty":"宋","verses":["吾观天地间，一一皆是画与诗。","渝川有二罗，画得天地之英奇。","大罗诗名撼湖海，小罗天机勃鬰不得已而水墨之。","摇毫造化已破碎，洒墨元气为淋漓。","嗟余老眼得一见，以手扪摸心然疑。","问君自古画有几，君今此画师者谁。","君言我以眼为手，天地万物皆吾师。","吾能得其意与理，貌取色相特其皮。","画成正未知似否，人人有眼谁可欺。","譬之禅宗要透脱，恋恋祖佛宁非痴。","作诗点出未来眼，一扫徐熙与郭熙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a62d4bb2-89a9-4a39-aa22-6e9ca0dec712","tags":[]},{"id":"poem-a96e699109aa96797dd982eb","title":"入睦州分水路忆刘长卿","author":"李嘉祐","dynasty":"唐","verses":["北阙忤明主，南方随白云。","沿洄滩草色，应接海鸥群。","建德潮已尽，新安江又分。","回看严子濑，朗咏谢安文。","雨过暮山碧，猨吟秋日曛。","吴洲不可到，刷鬓为思君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a31da724-61fb-4082-a5e3-ba1d3b7f2d9c","tags":[]},{"id":"poem-a97026042853580edf1fd82e","title":"望海","author":"周繇","dynasty":"唐","verses":["苍茫空泛日，四顾绝人烟。","半浸中华岸，旁通异域船。","岛间应有国，波外恐无天。","欲作乘槎客，翻愁去隔年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8bae582b-62ab-47f6-8d66-2f05b9594c1b","tags":[]},{"id":"poem-a982aa41a9da3c1c97bed541","title":"春陪相公看花宴会二首 二","author":"徐凝","dynasty":"唐","verses":["木兰花谢可怜条，远道音书转寂寥。","春去一年春又尽，几回空上望江桥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-485b786c-c2e9-4167-a5de-26b61e3c0aa5","tags":[]},{"id":"poem-a9877bdab7d4302a902c9a93","title":"摊破浣溪沙·手卷真珠上玉钩","author":"李璟","dynasty":"五代","verses":["手卷真珠上玉钩，依前春恨锁重楼。","风里落花谁是主？思悠悠。","青鸟不传云外信，丁香空结雨中愁。","回首绿波三楚暮，接天流。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-2","tags":[]},{"id":"poem-a9877f279e16e5b4ec62de4f","title":"巴江雨夜","author":"杨凭","dynasty":"唐","verses":["五岭天无雁，三巴客问津。","纷纷轻汉暮，漠漠暗江春。","青草连湖岸，繁花忆楚人。","芳菲无限路，几夜月明新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1c2374ee-4b03-4303-8bed-377a9dfd290a","tags":[]},{"id":"poem-a995547c8ee4e5549deabfba","title":"和彭进士感怀","author":"李咸用","dynasty":"唐","verses":["人生谁肯便甘休，遇酒逢花且共游。","若向云衢陪骥尾，直须天畔落旄头。","三编大雅曾关兴，一册南华旋解忧。","四海英雄多独断，不知何者是长筹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2ec90340-a1fe-4c02-9fc7-bf06b5767c08","tags":[]},{"id":"poem-a99c6dbcbd83e000b7c95c2f","title":"正卿借韵招同社候雨霁访梅次韵","author":"曾协","dynasty":"宋","verses":["看梅常拟到参横，最爱微霜堕太清。","轻棹幽探烦结约，繁花乱点要晴明。","直须香里同扶杖，莫问尊前几举觥。","谁向诗盟最先歃，定知一座自公倾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-98c04ae7-43f8-4e77-9bb1-972a8a9ce511","tags":[]},{"id":"poem-a9a1ee52ee4ead89d2e82573","title":"舟行怀阎士和","author":"皎然","dynasty":"唐","verses":["二月湖南春草徧，横山渡口花如霰。","相思一日在孤舟，空见归云两三片。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f152c170-82c8-4cc8-a1a7-ce1037f1569e","tags":[]},{"id":"poem-a9a51016af7bf377d1503763","title":"汉江临泛","author":"王维","dynasty":"唐","verses":["楚塞三湘接，荆门九派通。","江流天地外，山色有无中。","郡邑浮前浦，波澜动远空。","襄阳好风日，留醉与山翁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9080a103-2750-4b9b-a4fa-1167cd670a0c","tags":["唐诗三百首","山水","抒情","五言律诗"]},{"id":"poem-a9ae3f9c5094090056cefe37","title":"浣溪沙·寄严荪友","author":"纳兰性德","dynasty":"清","verses":["藕荡桥边理钓筒，苎萝西去五湖东。","笔床茶灶太从容。","况有短墙银杏雨，更兼高阁玉兰风。","画眉闲了画芙蓉。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-49","tags":[]},{"id":"poem-a9b4727a8d41436f86729490","title":"天下乐","author":"杨景贤","dynasty":"元","verses":["这和尚伏虎降龙信有之，京师，诸弟子，焚香点烛齐叩齿。","社火每鬼间着神，乐器中竹间着丝，闹起一座霸陵桥上市。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10101","tags":[]},{"id":"poem-a9b5e43b3bd92e84ea4f486c","title":"杨柳枝·春入行宫映翠微","author":"皇甫松","dynasty":"唐","verses":["春入行宫映翠微，玄宗侍女舞烟丝。","如今柳向空城绿，玉笛何人更把吹。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-20","tags":[]},{"id":"poem-a9b7d184e743af8e999be5b0","title":"渡西陵十六韵","author":"李绅","dynasty":"唐","verses":["雨送奔涛远，风收骇浪平。","截流张斾影，分岸走鼙声。","兽逐衔波涌，龟艨喷棹轻。","海门凝雾暗，江渚湿云横。","雁翼看舟子，鱼鳞辨水营。","骑交遮戍合，戈簇拥沙明。","谬履千夫长，将询百吏情。","下车占黍稷，冬雨害粢盛。","望祷依前圣，垂休翼厚生。","半江犹惨澹，全野已澄清。","爱景三辰朗，祥农万庾盈。","浦程通曲屿，海色媚重城。","弓日鞬櫜动，旗风虎豹争。","及郊挥白羽，入里卷红旌。","恺悌思陈力，端庄冀表诚。","临人与安俗，非止奉师贞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d9356725-b5ad-4a5b-9e36-8e31edb39bf6","tags":[]},{"id":"poem-a9bc77842a4f8e7b4d8dd8af","title":"旅馆三适  其二","author":"陈造","dynasty":"宋","verses":["隽永项上脔，红嫩劣带膋。","彼美大栏君，坐受群毛朝。","鼎湆走真味，正藉松炬烧。","芼我银丝窝，葱豉巧和调。","堇涂非所宜，淑郁如兰椒。","腹腴但下隶，膻根合藤条。","并填长翁腹，未觉喉牙摇。","但讶大嚼余，无补诗肠枵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5ce03931-542d-4c63-8535-2312b0ca2f8a","tags":[]},{"id":"poem-a9c0cc5b64028bcc02e21666","title":"力疾山下吴邨看杏花十九首 五","author":"司空图","dynasty":"唐","verses":["才情百巧鬬风光，却笑雕花刻叶忙。","熨帖新巾来与裹，犹看腾踏少年场。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9c4e22cc-f4d9-4fca-9b88-118e4869286d","tags":[]},{"id":"poem-a9d5f64e87b4dabd9f3f4847","title":"涪江风月","author":"鲜于侁","dynasty":"宋","verses":["涪江风月为谁清，莫向涪翁问姓名。","万古涪江流不尽，渔矶月似旧时明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-2ae46691-8d2a-4bc8-a804-28815611d72b","tags":[]},{"id":"poem-a9d7e9ee4d1664dcb1334c20","title":"画堂春·春波浅碧涨方池","author":"仲并","dynasty":"宋","verses":["春波浅碧涨方池。","池台深锁烟霏。","缓歌争胜早莺啼。","客忍轻归。","合坐香凝宿雾，垫巾梅插寒枝。","渐西蟾影漾馀辉。","醉倒谁知。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-192","tags":[]},{"id":"poem-a9dcd86ab2e9ad452dd751a5","title":"送臧子与子仪之楚州告免解二首  其一","author":"陈造","dynasty":"宋","verses":["二臧如静女，不受朱粉加。","尹姬望邢娥，宜著帝者家。","向来扬蛾眉，众喙怒以呀。","指玉谢坚洁，擘肌起疵瑕。","去汝忽若蜕，人与室俱遐。","玉台镜如月，满意事铅华。","九重访娟丽，万目看嫮姱。","当使听听者，昂首七香车。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-7245bb49-4309-4cb8-9d10-7d6500fc1aff","tags":[]},{"id":"poem-a9dcf4ee5bce75ba657982f1","title":"渔家傲·近日门前溪水涨","author":"欧阳修","dynasty":"宋","verses":["近日门前溪水涨。","郎船几度偷相访。","船小难开红斗帐。","无计向。","合欢影里空惆怅。","愿妾身为红菡萏。","年年生在秋江上。","重愿郎为花底浪。","无隔障。","随风逐雨长来往。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-784","tags":[]},{"id":"poem-a9e127c52393a2fba827e9d5","title":"萍乡春晚寓居（四首） 四","author":"沈彬","dynasty":"唐","verses":["叶老游蜂不更忙，春残去去好思量。","倚根托蒂花犹落，损力耗心谁可常。","江树不能留野水，晚烟多共恨斜阳。","感时伤事皆头白，几个渔竿遇帝主。","（见同治十一年刊锡荣纂《萍乡县志》卷六）（按：《萍乡县志》收沈诗为宋初之作，误。","民国间李有鋆纂《昭萍志略》卷十二已改归唐代。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ee08ced4-6557-4a01-a8fe-64daa24d7ee2","tags":[]},{"id":"poem-a9f564cbefdfcf8afb36ae99","title":"九月九日忆山东兄弟","author":"王维","dynasty":"唐","verses":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6bbd1c2c-8c43-4ffb-b7b3-506d74266cee","tags":["唐诗三百首","七言绝句","思乡","三年级上册","重阳节","小学古诗"]},{"id":"poem-aa001f609385a81e177028be","title":"采苹","author":"佚名","dynasty":"先秦","verses":["于以采苹？南涧之滨。于以采藻？于彼行潦。","于以盛之？维筐及筥。于以湘之？维锜及釜。","于以奠之？宗室牖下。谁其尸之？有齐季女。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-14","tags":[]},{"id":"poem-aa00ebfcb990251638f850b7","title":"驱竖子摘苍耳","author":"杜甫","dynasty":"唐","verses":["江上秋已分，林中瘴犹剧。","畦丁告劳苦，无以供日夕。","蓬莠独不焦，野蔬暗泉石。","卷耳况疗风，童儿且时摘。","侵星驱之去，烂熳任远适。","放筐亭午际，洗剥相蒙幂。","登床半生熟，下箸还小益。","加点瓜薤间，依稀橘奴迹。","乱世诛求急，黎民糠籺窄。","饱食复何心，荒哉膏粱客。","富家厨肉臭，战地骸骨白。","寄语恶少年，黄金且休掷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-15ebb60f-02a0-4915-900a-eade0191f674","tags":[]},{"id":"poem-aa036e80c844318f6e01c427","title":"点绛唇·璧月香风","author":"曾觌","dynasty":"宋","verses":["璧月香风，万家帘幕烟如昼。","闹蛾雪柳。","人似梅花瘦。","行乐清时，莫惜笙歌奏。","更阑后。","满斟金斗。","且醉厌厌酒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-356","tags":[]},{"id":"poem-aa1a0103c0badf95dff30b17","title":"秋夜达萧关","author":"于邺","dynasty":"唐","verses":["扰扰浮梁路，人忙月自闲。","去年为塞客，今夜宿萧关。","辞国几经岁，望乡空见山。","不知江叶下，又作布衣还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-26899957-16a6-43b4-b70e-7bfbb254b686","tags":[]},{"id":"poem-aa2165827407fbe3245699ee","title":"题岳州僧舍","author":"裴说","dynasty":"唐","verses":["喜到重湖北，孤州横晚烟。","鹭衔鱼入寺，鵶接饭随船。","松桧君山逈，菰蒲梦泽连。","与师吟论处，秋水浸遥天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-41c23948-3d4b-4b52-8489-153143a1e6ac","tags":[]},{"id":"poem-aa2449fe597cd7ecc549e1a9","title":"蝶恋花·醉别西楼醒不记","author":"晏几道","dynasty":"宋","verses":["醉别西楼醒不记。","春梦秋云，聚散真容易。","斜月半窗还少睡。","画屏闲展吴山翠。","衣上酒痕诗里字。","点点行行，总是凄凉意。","红烛自怜无好计。","夜寒空替人垂泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-21","tags":["宋词三百首"]},{"id":"poem-aa27746dd58baac489185b23","title":"惜分飞·泪湿阑干花著露","author":"毛滂","dynasty":"宋","verses":["泪湿阑干花著露。","愁到眉峰碧聚。","此恨平分取。","更无言语。","空相觑。","短雨残云无意绪。","寂寞朝朝暮暮。","今夜山深处。","断魂分付。","潮回去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-247","tags":["宋词三百首"]},{"id":"poem-aa28d6d2b2a60b42c5c4030c","title":"夜游宫·城上昏烟四敛","author":"方千里","dynasty":"宋","verses":["城上昏烟四敛。","画楼外、陡听更点。","千里相思梦中见。","恨年华，逐东流，随急箭。","帘影参差转。","夜初过、水沈烟乱。","剩枕馀衾故人远。","忆闲窗，亸云鬓，低粉面。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-543","tags":[]},{"id":"poem-aa2c406d2f14ac703810de77","title":"答西蜀欧阳侍郎颂（题拟） 二","author":"延沼","dynasty":"唐","verses":["甘露台前靡不逢，免将明暗諕盲聋。","当初贬着文殊处，笑杀寒山者老翁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4509753e-7731-4f28-bd9e-3767c6862427","tags":[]},{"id":"poem-aa2cbebb501d06744a1e1c95","title":"东宫生日六首 乙未","author":"林光朝","dynasty":"宋","verses":["应律随豳雅，旋杓建戌方。","前星迎霁色，重日丽晨光。","笙管青霞外，宫庭碧玉傍。","本支周道盛，羽翼汉图昌。","左右人皆正，刑名学未遑。","编年听司马，说礼付高堂。","天乐来三殿，人心系八荒。","黄华秋更媚，皓月闰偏长。","清赏新奎壁，承华旧典章。","维熊千岁祝，英略似君王。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1472a105-3626-44b0-a13a-20f0e1689da0","tags":[]},{"id":"poem-aa3b2366f32af067466a0571","title":"歌 三","author":"契此","dynasty":"唐","verses":["万法何殊心何异，何劳更用寻经义。","心王本自绝多知，智者只明无学地。","（以上三首又见《宗镜录》卷十八。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4968a968-2c4b-4421-81d1-99163fed2475","tags":[]},{"id":"poem-aa45b5b9ce187289181f6df3","title":"春江夕望","author":"卢纶","dynasty":"唐","verses":["洞庭芳草遍，楚客莫思归。","经难人空老，逢春鴈自飞。","东西兄弟远，存没友朋稀。","独立还垂泪，天南一布衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-31b1a00e-1ae0-42d5-9996-e5bf8beecbb6","tags":["洞庭湖"]},{"id":"poem-aa48fc48df49f8de662c0887","title":"黄子陂","author":"司空曙","dynasty":"唐","verses":["岸芳春色晓，水影夕阳微。","寂寂深烟里，渔舟夜不归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c14e9734-cec8-445e-8d03-88d75a42f48e","tags":[]},{"id":"poem-aa4ddaad2fdfcf023c492bd7","title":"送元二使安西","author":"王维","dynasty":"唐","verses":["渭城朝雨浥轻尘，客舍青青柳色新。","劝君更尽一杯酒，西出阳关无故人。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送元二使安西","tags":[]},{"id":"poem-aa50d420111c4f80196f5143","title":"浣溪沙·醉里惊从月窟来","author":"向子𬤇","dynasty":"宋","verses":["醉里惊从月窟来。","睡馀如梦蕊宫回。","碧云时度小崔嵬。","疑是海山怜我老，不论时节遣花开。","从今休数返魂梅。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-128","tags":[]},{"id":"poem-aa578eab00f18b1c3a78a3cc","title":"送僧之安南","author":"贯休","dynasty":"唐","verses":["安南千万里，师去趣何长。","鬓有炎州雪，心为异国香。","退牙山象恶，过海布帆荒。","早作归吴计，无忘父母乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-71cf5a48-286d-4038-ab39-a3753fb48425","tags":[]},{"id":"poem-aa63b91347857b9df8b8ed4d","title":"巫山一段云·萧氏贤夫妇","author":"柳永","dynasty":"宋","verses":["萧氏贤夫妇，茅家好弟兄。","羽轮飙驾赴层城。","高会尽仙卿。","一曲云谣为寿。","倒尽金壶碧酒。","醺酣争撼白榆花。","踏碎九光霞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-105","tags":[]},{"id":"poem-aa6f50c921ccb79d548f45a9","title":"春朝偶书","author":"赵崇嶓","dynasty":"宋","verses":["一夕春归桃李根，清寒犹勒艳阳魂。","雪霜雨露年年事，惟有梅花地位尊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ebcb074f-0675-4944-a388-d066f01366c6","tags":[]},{"id":"poem-aa73416433987fdcba97ac4f","title":"从郑少嘉求贡纲余茶  其一","author":"张栻","dynasty":"宋","verses":["贡包余璧小盘龙，独占人间第一功。","乞与清风行万里，为君一洗瘴云空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f18a7aa1-6624-4a4e-a65f-adb78c0bce97","tags":[]},{"id":"poem-aa7ad02a95626fa5bddba0af","title":"谢朱常侍寄贶蜀茶剡纸二首 一","author":"崔道融","dynasty":"唐","verses":["瑟瑟香尘瑟瑟泉，惊风骤雨起炉烟。","一瓯解却山中醉，便觉身轻欲上天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-df58e4c6-146a-4a87-8d30-73b746131439","tags":[]},{"id":"poem-aa7d90fc8ad4b92b79226437","title":"临江仙·十岁儿曹同砚席","author":"晁补之","dynasty":"宋","verses":["十岁儿曹同砚席，华裾织翠如葱。","一生心事醉吟中。","相逢俱白首，无语对西风。","莫道尊前情调减，衰颜得酒能红。","可怜此会意无穷。","夜阑人总睡，独绕菊花丛。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-189","tags":[]},{"id":"poem-aa7f3ac3661038e122d56498","title":"十二时偈 十二","author":"文偃","dynasty":"唐","verses":["人定亥，莫把三乘相疋配。","要知此意现真宗，密密心心超三昧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-04ab9997-34c2-4887-8427-b3fd5ec44984","tags":[]},{"id":"poem-aa841a179d2a099dd26c1d14","title":"题张于潜画轴五首  其三","author":"释居简","dynasty":"宋","verses":["老发鬅鬙两髻丫，天台山里老烟霞。","闾丘别后无踪迹，又在兰陵故相家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0b3f1b9b-d535-49c8-9754-c61d0587b6f9","tags":[]},{"id":"poem-aa8555dc9b36dc322d715fe7","title":"昆明池侍宴应制","author":"沈佺期","dynasty":"唐","verses":["武帝伐昆明，穿池习五兵。","水同河汉在，馆有豫章名。","我后光天德，垂衣文教成。","黩兵非帝念，劳物岂皇情。","春仗过鲸沼，云旗出凤城。","灵鱼衔宝跃，仙女废机迎。","柳拂旌门暗，兰依帐殿生。","还如流水曲，日晚棹歌清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-aa53e079-7b40-4f59-bffd-3f6b1841afa7","tags":[]},{"id":"poem-aa8c6e0d89c1f479d804cc68","title":"点绛唇·莫问重阳","author":"向子𬤇","dynasty":"宋","verses":["莫问重阳，黄花满地须游宴。","休论夷甸。","且作江山观。","百岁光阴，屈指今过半。","霜天晚。","眼昏花乱。","不见书空雁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-161","tags":[]},{"id":"poem-aa8cad89dcb7665bbfcb6fad","title":"点绛唇·咏风兰","author":"纳兰性德","dynasty":"清","verses":["别样幽芬，更无浓艳催开处。","凌波欲去，且为东风住。","忒煞萧疏，争奈秋如许。","还留取，冷香半缕，第一湘江雨。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-2","tags":[]},{"id":"poem-aa943d0ac296d0ecc0fde206","title":"旅夜书怀","author":"杜甫","dynasty":"唐","verses":["细草微风岸，危樯独夜舟。","星垂平野阔，月涌大江流。","名岂文章著，官因老病休。","飘飘何所似，天地一沙鸥。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f96506ea-e8ac-47e0-a0a6-ccd306e56645","tags":["唐诗三百首","写景","孤独","抒怀","五言律诗"]},{"id":"poem-aa9590a915763f86b5ce9d04","title":"绿头鸭・多丽·晚云收","author":"晁端礼","dynasty":"宋","verses":["晚云收，淡天一片琉璃。","烂银盘、来从海底，皓色千里澄辉。","莹无尘、素娥淡伫，静可数、丹桂参差。","玉露初零，金风未凛，一年无似此佳时。","露坐久，疏莹时度，乌鹊正南飞。","瑶台冷，栏干凭暖，玉下迟迟。","念佳人，音尘别后，对此应解相思。","最关情、漏声正永，暗断肠、花影偷移。","料得来宵，清光未减，阴晴天气又争知。","共凝恋、如今别后，还是隔年期。","人强健，清尊素影，长愿相随。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-62","tags":["宋词三百首"]},{"id":"poem-aa96ba32b31f48a1ca754f04","title":"春游乐","author":"李端","dynasty":"唐","verses":["游童苏合弹，倡女蒲葵扇。","初日映城时，相思忽相见。","褰裳蹋路草，理鬓回花面。","薄暮不同归，留情此芳甸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2859c7f7-5ebd-4ed0-8b4a-2d8212dbcc14","tags":[]},{"id":"poem-aa9af709d9b61a4855095095","title":"小重山·梁燕双飞画阁前","author":"毛熙震","dynasty":"五代","verses":["梁燕双飞画阁前，寂寥多少恨，懒孤眠。","晓来闲处想君怜，红罗帐，金鸭冷沉烟。","谁信损婵娟，倚屏啼玉箸，湿香钿。","四肢无力上秋千，群花谢，愁对艳阳天。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-2","tags":[]},{"id":"poem-aa9c2d678c43f3dbf6af3d7b","title":"过骊山","author":"孟迟","dynasty":"唐","verses":["冷日微烟渭水愁，华清宫树不胜秋。","霓裳一曲千门锁，白尽梨园弟子头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8c7331f5-925d-4b37-b7a2-f94827e2a98f","tags":[]},{"id":"poem-aa9eebfd687f90afd6e6bdf5","title":"点绛唇·天末相逢","author":"洪适","dynasty":"宋","verses":["天末相逢，醉中不讶车茵污。","一声鸣橹。","惊散眠沙鹭。","我是行人，却送行人去。","听金缕。","莫辞甘醑。","别泪飞寒雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-715","tags":[]},{"id":"poem-aaac0efa672e44ada8b97ce1","title":"闻笛","author":"赵嘏","dynasty":"唐","verses":["谁家吹笛画楼中，断续声随断续风。","响遏行云横碧落，清和冷月到帘栊。","兴来三弄有桓子，赋就一篇怀马融。","曲罢不知人在否，余音嘹亮尚飘空。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-聞笛","tags":[]},{"id":"poem-aaac345cdb2915d9634008a3","title":"乌夜啼·月儿犹未全明","author":"张镃","dynasty":"宋","verses":["月儿犹未全明。","乞怜生。","几片彩云来去、更风轻。","应见我。","行又坐。","苦凝情。","卷起帘儿不睡、到三更。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-327","tags":[]},{"id":"poem-aaace12baf10b4b0b2e3f0b0","title":"过宋州","author":"李端","dynasty":"唐","verses":["睢阳陷虏日，外绝救兵来。","世乱忠臣死，时清明主哀。","荒郊春草徧，故垒野花开。","欲为将军哭，东流水不回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6381e1ed-6c1f-4b0a-b4aa-26fd2370c2c4","tags":[]},{"id":"poem-aab51654166167eaecbbedbb","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["婆婆，你还死教奴家怎支吾？你若死教我怎生度？我千辛万苦回护丈夫，如今到此难回护。","我只愁母死难留父，况衣衫尽解，囊箧又无。","(外叫净介唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5079","tags":[]},{"id":"poem-aab52d0081b0d39a3778e622","title":"宴琼林·遽暖间俄寒","author":"黄裳","dynasty":"宋","verses":["遽暖间俄寒，妙用向园林，难问春意。","万般声与色，自闻雷、便作浮华人世。","红娇翠软，谁顿悟、天机此理。","似韶容、可驻无人会，且忘言闲醉。","当度仙家长日，向人间、闲看佳丽。","念远处有东风在，梦悠悠往事。","桃溪近、幽香远远，谩凝望、落花流水。","桂华中、珠佩随轩去，还从卖花市。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-624","tags":[]},{"id":"poem-aab65e6589a935bbb8f17469","title":"渔家傲·六月炎蒸何太盛","author":"欧阳修","dynasty":"宋","verses":["六月炎蒸何太盛。","海榴灼灼红相映。","天外奇峰千掌迥。","风影定。","汉宫圆扇初成咏。","珠箔初褰深院静。","绛绡衣窄冰肤莹。","睡起日高堆酒兴。","厌厌病。","宿酲和梦何时醒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-712","tags":[]},{"id":"poem-aab85a9c93978cccfd1093db","title":"红芍药","author":"施惠《幽闺记》","dynasty":"元","verses":["(外)兵扰攘，阻隔关津。","思量着，役梦劳魂。","(丑)眼见得家中受危闲，望吾乡，有家难齐。","(老旦)孩儿，历尽了苦共辛，娘逢人见人寻问。","只愁你举目无亲，子父每何处厮认？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3033","tags":[]},{"id":"poem-aac2ef1411b4a09a893b411c","title":"天仙子·深夜归来长酩酊","author":"韦庄","dynasty":"五代","verses":["深夜归来长酩酊，扶入流苏犹未醒。","醺醺酒气麝兰和，惊睡觉，笑呵呵，长道人生能几何。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-8","tags":[]},{"id":"poem-aac70bf72f8ac1250cef13a2","title":"洛阳道","author":"任翻","dynasty":"唐","verses":["憧憧洛阳道，尘下生青草。","行者岂无家，无人在家老。","鸡鸣前结束，争去恐不早。","百年路傍尽，白日车中晓。","求富江海狭，取贵山岳小。","二端立在途，奔走无由了。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2171e44d-f83c-4277-9155-6d06f66a9fab","tags":[]},{"id":"poem-aac9fa82d86c062b5b4aeaf0","title":"朝中措·酴醿芳架引繁英","author":"曹勋","dynasty":"宋","verses":["酴醿芳架引繁英。","香远透帘清。","更与洛阳花市，一齐移在宫庭。","琉璃万朵，娇红嫩紫，总是嘉名。","殿阁真仙同赏，天颜喜入欢声。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-157","tags":[]},{"id":"poem-aaca477503d1ff89841b4165","title":"虞美人·烟霄脉脉停机杼","author":"韩元吉","dynasty":"宋","verses":["烟霄脉脉停机杼。","双鹊飞来语。","踏歌声转玉钩斜。","好是满天风露、一池花。","离多会少从来有。","不似人间久。","欢情谁道隔年迟。","须信仙家日月、未多时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-811","tags":[]},{"id":"poem-aace647fb839d721266b7a98","title":"嘉禾合颖","author":"孟简","dynasty":"唐","verses":["玉烛将成岁，封人亦自歌。","八方沾圣泽，异亩发嘉禾。","共秀芳何远，连茎瑞且多。","颖低甘露滴，影乱惠风过。","表稔由神化，为祥识气和。","因知兴嗣岁，王道旧无颇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5727b7ac-a026-4b83-bb4b-b8fe0706636d","tags":[]},{"id":"poem-aad13d161298fa272601f79f","title":"题尉迟将军新庙","author":"高适","dynasty":"唐","verses":["周室既板荡，贼臣立婴儿。","将军独激昂，誓欲酬恩私。","孤城日无援，高节终可悲。","家国共沦亡，精魂空在斯。","沈沉积冤气，寂寂无人知。","良牧怀深仁，与君建明祠。","父子俱血食，轩车每逶迤。","我来荐苹蘩，感叹兴此词。","晨光上阶闼，杀气翻旌旗。","明明幽冥理，至诚信莫欺。","唯夫二千石，多庆方自兹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d44f2dfd-d7d4-4bab-80eb-de60e198953f","tags":[]},{"id":"poem-aad79e060c36f206c820c363","title":"清平乐·将愁不去","author":"纳兰性德","dynasty":"清","verses":["将愁不去，秋色行难住。","六曲屏山深院宇。","日日风风雨雨。","雨晴篱菊初香，人言此日重阳。","回首凉云暮叶，黄昏无限思量。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-65","tags":[]},{"id":"poem-aada14987a5ab11521719c49","title":"樛木","author":"佚名","dynasty":"先秦","verses":["南有樛木，葛藟累之。乐只君子，福履绥之。","南有樛木，葛藟荒之。乐只君子，福履将之。","南有樛木，葛藟萦之。乐只君子，福履成之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-3","tags":[]}];
